CREATE OR REPLACE FUNCTION private.apply_inventory_reclass_moves_set_v1(p_actor_id uuid, p_command_id text, p_expected_revision bigint, p_moves jsonb, p_batch_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior_action_context text:=coalesce(current_setting('gnc.row_actions_v3070',true),'');

  actor_profile public.profiles%rowtype;
  actor_role text;
  actor_username text;
  is_manager boolean;
  current_revision bigint;
  source_count integer;
  line_count integer;
  result_rows jsonb;
  result_movements jsonb;
  child_ids jsonb;
  safe_fields text[]:=array['itemcode','commonname','contsize','locationcode','source','warehousei','warehouseid','season',
    'qualitycode','field_tag_color','fieldtagcolor','s_lts','plantgroupcode','listprice','itemspec','desigitem','desigcust','desigloc','warehousename','equiv_unit','brand','hz','priority','photo_url','photo_link','photo_name','photo_expires_at','photos','photo_date','date_completed','spec','caliper','loc_match_pct','loc_match_qty','loc_photo_match','match','initial_photo_match_qty','pic_note','av_note','pick_note','sales_note','locationnote','locationptn1',
    'saleyear','blockalpha','blocknumber','bay','grower','si_lts','a_lts','ai_lts','varietycode','genusname','botanicalname',
    'reversecommon','sortnamevariety','containersort','nationalaccount','salesrepid','salesrepname','printedcontainercode'];
  zero_fields text[]:=array['ptronhand','ptravailable','ptrreviewed','season_supply','season_oh','season_demand','season_available',
    'ext_ptronhand','end_cap_qty','loc_match_qty','initial_ptr','largeptrqty','maxorderquantity'];
begin
  select * into actor_profile from public.profiles p where p.id=p_actor_id and p.disabled_at is null
    and (p.locked_until is null or p.locked_until<=now()) and not p.must_change_password;
  if actor_profile.id is null then raise exception using errcode='42501',message='INVENTORY_RECLASS_PROFILE_INACTIVE'; end if;
  actor_role := CASE WHEN private.inventory_unrestricted_actor_v23155(actor_profile) THEN 'ADMIN' ELSE private.normalized_profile_role(actor_profile.role) END;
  actor_username:=lower(btrim(coalesce(actor_profile.username,'')));
  is_manager:=actor_role in ('ADMIN','ADMINISTRATOR','MANAGER');

  create temporary table if not exists reclass_batch_source_before_v1(
    source_index integer primary key,like public.ph_master_inventory) on commit drop;
  create temporary table if not exists reclass_batch_source_after_v1(
    source_index integer primary key,like public.ph_master_inventory) on commit drop;
  create temporary table if not exists reclass_batch_target_before_v1(
    source_index integer,destination_season text,like public.ph_master_inventory,
    primary key(source_index,destination_season)) on commit drop;
  create temporary table if not exists reclass_batch_target_after_v1(
    source_index integer,destination_season text,like public.ph_master_inventory,
    primary key(source_index,destination_season)) on commit drop;
  create temporary table if not exists reclass_batch_sources_v1(
    source_index integer primary key,source_uid text unique,child_command text not null,child_request_id uuid not null,
    source_identity jsonb not null,source_lineage text not null,source_season text not null,
    source_stem text not null,source_on_hand numeric,source_available numeric,total_quantity numeric not null default 0
  ) on commit drop;
  create temporary table if not exists reclass_batch_lines_v1(
    source_index integer not null,line_index integer not null,direction text not null,destination_season text not null,
    quantity numeric not null,primary key(source_index,line_index)
  ) on commit drop;
  create temporary table if not exists reclass_batch_targets_v1(
    source_index integer not null,destination_season text not null,destination_lot text not null,quantity numeric not null,
    destination_uid text not null,destination_lineage text,destination_after jsonb,match_count integer not null default 0,
    primary key(source_index,destination_season)
  ) on commit drop;
  create temporary table if not exists reclass_batch_source_json_v1(
    source_index integer primary key,source_before jsonb not null,source_after jsonb not null) on commit drop;
  create temporary table if not exists reclass_batch_target_json_v1(
    source_index integer not null,destination_season text not null,destination_before jsonb,destination_after jsonb not null,
    primary key(source_index,destination_season)) on commit drop;
  truncate table pg_temp.reclass_batch_sources_v1,pg_temp.reclass_batch_lines_v1,pg_temp.reclass_batch_targets_v1;
  truncate table pg_temp.reclass_batch_source_before_v1,pg_temp.reclass_batch_source_after_v1,
    pg_temp.reclass_batch_target_before_v1,pg_temp.reclass_batch_target_after_v1,
    pg_temp.reclass_batch_source_json_v1,pg_temp.reclass_batch_target_json_v1;

  insert into pg_temp.reclass_batch_source_before_v1
  select e.ordinality::integer,m.*
  from jsonb_array_elements(p_moves) with ordinality e(value,ordinality)
  -- reclass-source-alias-v2388: prefer UID, exact lot, then the deterministic current split row.
  join lateral (
    select candidate.* from public.ph_master_inventory candidate
    where candidate.unique_id=btrim(coalesce(e.value#>>'{source,uniqueId}',''))
      or (upper(btrim(coalesce(candidate.itemcode,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,itemcode}','')))
        and upper(btrim(coalesce(candidate.locationcode,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,locationcode}',''))))
    order by
      (candidate.unique_id=btrim(coalesce(e.value#>>'{source,uniqueId}',''))) desc,
      (upper(btrim(coalesce(candidate.lotcode,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,lotcode}','')))) desc,
      (upper(btrim(coalesce(candidate.season,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,season}','')))) desc,
      (upper(btrim(coalesce(candidate.contsize,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,contsize}','')))) desc,
      candidate.unique_id
    limit 1
  ) m on true
  order by e.ordinality;
  insert into pg_temp.reclass_batch_source_json_v1(source_index,source_before,source_after)
    select b.source_index,to_jsonb(b)-'source_index','{}'::jsonb
    from pg_temp.reclass_batch_source_before_v1 b;
  insert into pg_temp.reclass_batch_sources_v1(source_index,source_uid,child_command,child_request_id,
    source_identity,source_lineage,source_season,source_stem,source_on_hand,source_available)
  select e.ordinality::integer,b.unique_id::text,
    'reclass-batch:'||left(encode(extensions.digest(convert_to(p_command_id||':'||e.ordinality::text,'UTF8'),'sha256'),'hex'),40),
    gen_random_uuid(),jsonb_build_object('unique_id',j.source_before->'unique_id','itemcode',j.source_before->'itemcode',
      'contsize',j.source_before->'contsize','locationcode',j.source_before->'locationcode','lotcode',j.source_before->'lotcode',
      'season',j.source_before->'season','ptronhand',j.source_before->'ptronhand','ptravailable',j.source_before->'ptravailable'),
    private.ph_master_inventory_lineage_key_v1(j.source_before),
    upper(btrim(coalesce(nullif(b.season::text,''),nullif(regexp_replace(coalesce(b.lotcode::text,''),'^.*[.]',''),''),''))),
    regexp_replace(b.lotcode::text,'[.][^.]+$',''),private.reclass_numeric_v1(b.ptronhand::text),
    private.reclass_numeric_v1(b.ptravailable::text)
  from jsonb_array_elements(p_moves) with ordinality e(value,ordinality)
  join pg_temp.reclass_batch_source_before_v1 b on b.source_index=e.ordinality
  join pg_temp.reclass_batch_source_json_v1 j using(source_index)
  order by e.ordinality;
  get diagnostics source_count=row_count;
  if source_count<>jsonb_array_length(p_moves) then raise exception using errcode='PT409',message='INVENTORY_RECLASS_SOURCE_MISSING'; end if;
  if exists(select 1 from jsonb_array_elements(p_moves) with ordinality e(value,ordinality)
    where not exists(select 1 from public.ph_master_inventory exact_source
        where exact_source.unique_id=btrim(coalesce(e.value#>>'{source,uniqueId}','')))
      and (select count(*) from public.ph_master_inventory candidate
        where upper(btrim(coalesce(candidate.itemcode,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,itemcode}','')))
          and upper(btrim(coalesce(candidate.locationcode,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,locationcode}','')))
          and upper(btrim(coalesce(candidate.lotcode,'')))=upper(btrim(coalesce(e.value#>>'{source,identity,lotcode}',''))))>1) then
    raise exception using errcode='PT409',message='INVENTORY_RECLASS_SOURCE_AMBIGUOUS';
  end if;
  analyze pg_temp.reclass_batch_sources_v1;

  if not is_manager and exists(select 1 from pg_temp.reclass_batch_sources_v1 s
    join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    where not private.inventory_row_assigned_to_actor_v2392(actor_username,b.unique_id,b.itemcode)) then
    raise exception using errcode='42501',message='DRIVE_RECLASS_ROW_NOT_ASSIGNED';
  end if;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 s
    join pg_temp.reclass_batch_source_before_v1 b using(source_index) where
    s.source_identity-array['unique_id','itemcode','contsize','locationcode','lotcode','season','ptronhand','ptravailable']<>'{}'::jsonb
    or s.source_identity->>'unique_id' is distinct from b.unique_id::text
    or s.source_identity->>'itemcode' is distinct from b.itemcode::text
    or s.source_identity->>'contsize' is distinct from b.contsize::text
    or s.source_identity->>'locationcode' is distinct from b.locationcode::text
    or s.source_identity->>'lotcode' is distinct from b.lotcode::text
    or s.source_identity->>'season' is distinct from b.season::text
) then
    raise exception using errcode='PT409',message='INVENTORY_RECLASS_SOURCE_CHANGED';
  end if;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 s join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    where b.lotcode::text !~ '^.+[.](F1|S1|U1|U2|U3|X|Y|Z)$') then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_LOT_INVALID';
  end if;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 s join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    where upper(substring(b.lotcode::text from '[.]([^.]+)$')) is distinct from s.source_season) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_LOT_SEASON_AMBIGUOUS';
  end if;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 s where s.source_on_hand is null or s.source_available is null) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_QUANTITY_UNKNOWN';
  end if;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 s join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    where
    (select count(*) from public.ph_master_inventory m
      where coalesce(m.warehouseid,m.warehousei,'')=coalesce(b.warehouseid::text,b.warehousei::text,'')
        and coalesce(m.itemcode,'')=coalesce(b.itemcode::text,'')
        and coalesce(m.contsize,'')=coalesce(b.contsize::text,'')
        and coalesce(m.locationcode,'')=coalesce(b.locationcode::text,'')
        and coalesce(m.lotcode,'')=coalesce(b.lotcode::text,'')
        and coalesce(m.source,'')=coalesce(b.source::text,'')
        and coalesce(m.desigitem,'')=coalesce(b.desigitem::text,'')
        and coalesce(m.desigcust,'')=coalesce(b.desigcust::text,'')
        and coalesce(m.desigloc,'')=coalesce(b.desigloc::text,''))<>1) then
    raise exception using errcode='PT409',message='INVENTORY_RECLASS_SOURCE_AMBIGUOUS';
  end if;

  insert into pg_temp.reclass_batch_lines_v1(source_index,line_index,direction,destination_season,quantity)
  select s.source_index,l.ordinality::integer,l.value->>'direction',upper(btrim(l.value->>'destinationSeason')),
    private.reclass_numeric_v1(l.value->>'quantity')
  from jsonb_array_elements(p_moves) with ordinality m(value,ordinality)
  join pg_temp.reclass_batch_sources_v1 s on s.source_index=m.ordinality
  cross join lateral jsonb_array_elements(m.value->'lines') with ordinality l(value,ordinality);
  get diagnostics line_count=row_count;
  analyze pg_temp.reclass_batch_lines_v1;
  if line_count>100 or exists(select 1 from pg_temp.reclass_batch_lines_v1 l
    where l.direction is null or l.direction not in ('move_up','move_down') or l.destination_season is null
      or l.destination_season not in ('F1','S1','U1','U2','U3','X','Y','Z')
      or l.destination_season=(select s.source_season from pg_temp.reclass_batch_sources_v1 s where s.source_index=l.source_index)
      or l.quantity is null or l.quantity<1 or l.quantity<>trunc(l.quantity) or l.quantity>2147483647) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_LINE_INVALID';
  end if;
  -- reclass-move-up-open-stock-v2390: cap aggregate Move Up by the source lot's pre-move S_LTS.
  if exists(
    select 1 from pg_temp.reclass_batch_lines_v1 l
      join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    group by upper(btrim(coalesce(b.itemcode::text,''))),upper(btrim(coalesce(b.lotcode::text,'')))
    having sum(case when l.direction='move_up' then l.quantity else 0 end)
      > greatest(0,min(coalesce(private.reclass_numeric_v1(b.s_lts::text),0)))
  ) then raise exception using errcode='22023',message='INVENTORY_RECLASS_MOVE_UP_OPEN_STOCK_EXCEEDED'; end if;
  update pg_temp.reclass_batch_sources_v1 s set total_quantity=q.quantity
  from (select l.source_index,sum(l.quantity) quantity from pg_temp.reclass_batch_lines_v1 l group by l.source_index) q
  where q.source_index=s.source_index;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 s where s.total_quantity>s.source_on_hand
      or s.total_quantity>s.source_available) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_QUANTITY_UNDERFLOW';
  end if;
  insert into pg_temp.reclass_batch_targets_v1(source_index,destination_season,destination_lot,quantity,destination_uid)
  select s.source_index,l.destination_season,s.source_stem||'.'||l.destination_season,sum(l.quantity),gen_random_uuid()::text
  from pg_temp.reclass_batch_sources_v1 s join pg_temp.reclass_batch_lines_v1 l using(source_index)
  group by s.source_index,l.destination_season,s.source_stem;
  analyze pg_temp.reclass_batch_targets_v1;
  update pg_temp.reclass_batch_targets_v1 t set destination_uid=case when x.matches=1 then x.destination_uid else t.destination_uid end,
    match_count=x.matches
  from (select t.source_index,t.destination_season,count(m.unique_id)::integer matches,min(m.unique_id) destination_uid
    from pg_temp.reclass_batch_targets_v1 t join pg_temp.reclass_batch_sources_v1 s using(source_index)
    join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    left join public.ph_master_inventory m on
      upper(btrim(coalesce(m.itemcode,'')))=upper(btrim(coalesce(b.itemcode::text,'')))
      and upper(btrim(coalesce(m.locationcode,'')))=upper(btrim(coalesce(b.locationcode::text,'')))
      and upper(btrim(coalesce(m.lotcode,'')))=upper(btrim(coalesce(t.destination_lot,'')))
    group by t.source_index,t.destination_season) x
  where x.source_index=t.source_index and x.destination_season=t.destination_season;
  if exists(select 1 from pg_temp.reclass_batch_targets_v1 where match_count>1) then
    raise exception using errcode='PT409',message='INVENTORY_RECLASS_DESTINATION_AMBIGUOUS';
  end if;
  if exists(select 1 from pg_temp.reclass_batch_targets_v1 t
    join public.ph_master_inventory m on m.unique_id=t.destination_uid
    where upper(btrim(coalesce(m.season::text,''))) is distinct from t.destination_season) then
    raise exception using errcode='PT409',message='INVENTORY_RECLASS_DESTINATION_SEASON_MISMATCH';
  end if;
  insert into pg_temp.reclass_batch_target_before_v1
    select t.source_index,t.destination_season,m.* from pg_temp.reclass_batch_targets_v1 t
    join public.ph_master_inventory m on m.unique_id=t.destination_uid where t.match_count=1;
  insert into pg_temp.reclass_batch_target_json_v1(source_index,destination_season,destination_before,destination_after)
    select b.source_index,b.destination_season,to_jsonb(b)-array['source_index','destination_season'],'{}'::jsonb
    from pg_temp.reclass_batch_target_before_v1 b;
  if exists(select 1 from pg_temp.reclass_batch_target_before_v1 b
    where private.reclass_numeric_v1(b.ptronhand::text) is null
      or private.reclass_numeric_v1(b.ptravailable::text) is null) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_DESTINATION_QUANTITY_UNKNOWN';
  end if;
  update pg_temp.reclass_batch_targets_v1 t set destination_after=(
    select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb) from pg_temp.reclass_batch_sources_v1 s
    join pg_temp.reclass_batch_source_json_v1 sj using(source_index)
    cross join lateral jsonb_each(sj.source_before) e where s.source_index=t.source_index and e.key=any(safe_fields))
    ||jsonb_build_object('unique_id',t.destination_uid,'lotcode',t.destination_lot,'season',t.destination_season,'saleyear',split_part(t.destination_lot,'.',1),
      'last_updated',clock_timestamp(),'concat','reclass-move:'||encode(extensions.digest(convert_to(p_command_id||':'||t.destination_uid,'UTF8'),'sha256'),'hex'))
    ||(select coalesce(jsonb_object_agg(z.field,'0'::jsonb),'{}'::jsonb) from unnest(zero_fields) z(field))
    ||jsonb_build_object('ptronhand',t.quantity::text,'ptravailable',t.quantity::text)||(select jsonb_build_object('s_lts',coalesce((select mode() within group(order by private.reclass_numeric_v1(m.s_lts))
        from public.ph_master_inventory m where upper(btrim(coalesce(m.itemcode,'')))=upper(btrim(coalesce(sj.source_before->>'itemcode','')))
          and upper(btrim(coalesce(m.lotcode,'')))=upper(btrim(coalesce(t.destination_lot,'')))),0)::text)
    ||jsonb_build_object('loc_photo_match',case
      -- reclass-batch-evidence-v2387: retain exact location evidence on both rows.
      when nullif(btrim(sj.source_before->>'loc_photo_match'),'') is not null
        then private.reclass_numeric_v1(sj.source_before->>'loc_photo_match')
      when private.reclass_numeric_v1(sj.source_before->>'loc_match_pct')>0
        then round(t.quantity*private.reclass_numeric_v1(sj.source_before->>'loc_match_pct')/100.0)
      else null end)
    from pg_temp.reclass_batch_source_json_v1 sj where sj.source_index=t.source_index)
    where t.match_count=0;
  update pg_temp.reclass_batch_targets_v1 t set destination_lineage=case when t.match_count=1
      then private.ph_master_inventory_lineage_key_v1(j.destination_before)
      else private.ph_master_inventory_lineage_key_v1(t.destination_after) end
    from pg_temp.reclass_batch_target_json_v1 j
    where t.match_count=1 and j.source_index=t.source_index and j.destination_season=t.destination_season;
  update pg_temp.reclass_batch_targets_v1 t set destination_lineage=private.ph_master_inventory_lineage_key_v1(t.destination_after)
    where t.match_count=0;
  if exists(select 1 from pg_temp.reclass_batch_sources_v1 group by source_lineage having count(*)>1)
    or exists(select 1 from pg_temp.reclass_batch_targets_v1 group by destination_lineage having count(*)>1)
    or exists(select 1 from pg_temp.reclass_batch_sources_v1 s join pg_temp.reclass_batch_targets_v1 t
      on t.destination_lineage=s.source_lineage) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_OVERLAP_INVALID';
  end if;
  insert into private.ph_inventory_reclass_commands_v1(request_id,actor_id,command_id,request,result)
  select s.child_request_id,p_actor_id,s.child_command,jsonb_build_object('expectedRevision',p_expected_revision+case when s.source_index=1 then 0 else 1 end,
    'sourceUid',s.source_uid,'sourceIdentity',s.source_identity,'lines',m.value->'lines'),'{}'::jsonb
  from pg_temp.reclass_batch_sources_v1 s join jsonb_array_elements(p_moves) with ordinality m(value,ordinality)
    on m.ordinality=s.source_index order by s.source_index;

  perform set_config('gnc.row_actions_v3070',(select jsonb_object_agg(entry.key,entry.value)::text from (
    select private.action_move_map_v3070(jsonb_agg(jsonb_build_object('from_uid',s.source_uid,'from_lot',b.lotcode,
      'from_location',b.locationcode,'to_uid',t.destination_uid,'to_lot',t.destination_lot,'to_location',b.locationcode,
      'direction',l.direction,'quantity',l.quantity)),p_actor_id,s.child_command)::jsonb as per_source
    from pg_temp.reclass_batch_sources_v1 s join pg_temp.reclass_batch_source_before_v1 b using(source_index)
    join pg_temp.reclass_batch_lines_v1 l using(source_index) join pg_temp.reclass_batch_targets_v1 t using(source_index,destination_season)
    group by s.source_index,s.child_command) groups cross join lateral jsonb_each(per_source) entry),true);
  with updated_sources as (
    update public.ph_master_inventory m set ptronhand=(s.source_on_hand-s.total_quantity)::text,
      ptravailable=(s.source_available-s.total_quantity)::text,last_updated=clock_timestamp()
    from pg_temp.reclass_batch_sources_v1 s where m.unique_id=s.source_uid
    returning m.*
  )
  insert into pg_temp.reclass_batch_source_after_v1
    select s.source_index,u.* from updated_sources u join pg_temp.reclass_batch_sources_v1 s on s.source_uid=u.unique_id;
  with updated_targets as (
    update public.ph_master_inventory m set ptronhand=(private.reclass_numeric_v1(b.ptronhand::text)+t.quantity)::text,
      ptravailable=(private.reclass_numeric_v1(b.ptravailable::text)+t.quantity)::text,last_updated=clock_timestamp()
    from pg_temp.reclass_batch_targets_v1 t join pg_temp.reclass_batch_target_before_v1 b
      using(source_index,destination_season)
    where t.match_count=1 and m.unique_id=t.destination_uid
    returning m.*
  )
  insert into pg_temp.reclass_batch_target_after_v1
    select t.source_index,t.destination_season,u.* from updated_targets u
    join pg_temp.reclass_batch_targets_v1 t on t.destination_uid=u.unique_id;
  with inserted_targets as (
    insert into public.ph_master_inventory as inserted
    select populated_destination.*
    from pg_temp.reclass_batch_targets_v1 t
    cross join lateral jsonb_populate_record(null::public.ph_master_inventory,t.destination_after) as populated_destination
    where t.match_count=0 order by t.source_index,t.destination_season
    returning inserted.*
  )
  insert into pg_temp.reclass_batch_target_after_v1
    select t.source_index,t.destination_season,i.* from inserted_targets i
    join pg_temp.reclass_batch_targets_v1 t on t.destination_uid=i.unique_id;
  update pg_temp.reclass_batch_source_json_v1 j set source_after=to_jsonb(a)-'source_index'
    from pg_temp.reclass_batch_source_after_v1 a where a.source_index=j.source_index;
  update pg_temp.reclass_batch_target_json_v1 j set destination_after=to_jsonb(a)-array['source_index','destination_season']
    from pg_temp.reclass_batch_target_after_v1 a
    where a.source_index=j.source_index and a.destination_season=j.destination_season;
  insert into pg_temp.reclass_batch_target_json_v1(source_index,destination_season,destination_before,destination_after)
    select a.source_index,a.destination_season,null,to_jsonb(a)-array['source_index','destination_season']
    from pg_temp.reclass_batch_target_after_v1 a
    where not exists(select 1 from pg_temp.reclass_batch_target_json_v1 j
      where j.source_index=a.source_index and j.destination_season=a.destination_season);
  -- AFTER STATEMENT season propagation has completed; freeze the current rows.
  update pg_temp.reclass_batch_source_json_v1 j set source_after=to_jsonb(m) from public.ph_master_inventory m where m.unique_id=j.source_after->>'unique_id';
  update pg_temp.reclass_batch_target_json_v1 j set destination_after=to_jsonb(m) from public.ph_master_inventory m where m.unique_id=j.destination_after->>'unique_id';
  insert into private.ph_inventory_reclass_import_aliases_v1(lineage_key,canonical_unique_id,request_id)
  select t.destination_lineage,t.destination_uid,s.child_request_id
  from pg_temp.reclass_batch_targets_v1 t join pg_temp.reclass_batch_sources_v1 s using(source_index)
  on conflict(lineage_key) do update set canonical_unique_id=excluded.canonical_unique_id,request_id=excluded.request_id
  where private.ph_inventory_reclass_import_aliases_v1.canonical_unique_id=excluded.canonical_unique_id;
  if exists(select 1 from pg_temp.reclass_batch_targets_v1 t
    where not exists(select 1 from private.ph_inventory_reclass_import_aliases_v1 a
      where a.lineage_key=t.destination_lineage and a.canonical_unique_id=t.destination_uid)) then
    raise exception using errcode='PT409',message='INVENTORY_RECLASS_DESTINATION_AMBIGUOUS';
  end if;

  insert into private.ph_inventory_reclass_movements_v1(request_id,line_index,direction,destination_season,quantity,
    source_unique_id,destination_unique_id,source_lineage_key,destination_lineage_key,source_identity,destination_identity,
    source_before,source_after,destination_before,destination_after)
  select s.child_request_id,l.line_index,l.direction,l.destination_season,l.quantity,s.source_uid,t.destination_uid,
    s.source_lineage,t.destination_lineage,
    jsonb_build_object('unique_id',s.source_uid,'itemcode',sj.source_before->'itemcode','contsize',sj.source_before->'contsize',
      'locationcode',sj.source_before->'locationcode','lotcode',sj.source_before->'lotcode','season',sj.source_before->'season',
      'source',sj.source_before->'source','warehouseid',coalesce(sj.source_before->>'warehouseid',sj.source_before->>'warehousei'),
      'desigitem',sj.source_before->'desigitem','desigcust',sj.source_before->'desigcust','desigloc',sj.source_before->'desigloc'),
    jsonb_build_object('unique_id',t.destination_uid,'itemcode',sj.source_before->'itemcode','contsize',sj.source_before->'contsize',
      'locationcode',sj.source_before->'locationcode','lotcode',to_jsonb(t.destination_lot),'season',to_jsonb(t.destination_season),
      'source',sj.source_before->'source','warehouseid',coalesce(sj.source_before->>'warehouseid',sj.source_before->>'warehousei'),
      'desigitem',sj.source_before->'desigitem','desigcust',sj.source_before->'desigcust','desigloc',sj.source_before->'desigloc'),
    sj.source_before,sj.source_after,tj.destination_before,tj.destination_after
  from pg_temp.reclass_batch_lines_v1 l
  join pg_temp.reclass_batch_sources_v1 s using(source_index)
  join pg_temp.reclass_batch_targets_v1 t using(source_index,destination_season)
  join pg_temp.reclass_batch_source_json_v1 sj using(source_index)
  join pg_temp.reclass_batch_target_json_v1 tj using(source_index,destination_season);

  insert into public.ph_inventory_transactions(unique_id,action,actor_id,actor_username,actor_display,source_table,source_unique_id,
    destination_table,destination_unique_id,source_itemcode,source_lotcode,source_locationcode,destination_itemcode,
    destination_lotcode,destination_locationcode,quantity,source_before,source_after,destination_before,destination_after,
    status,event_type,raw_payload,search_text)
  select gen_random_uuid()::text,l.direction,p_actor_id,actor_profile.username,coalesce(actor_profile.display_name,actor_profile.username),
    'ph_master_inventory',s.source_uid,'ph_master_inventory',t.destination_uid,sj.source_before->>'itemcode',sj.source_before->>'lotcode',
    sj.source_before->>'locationcode',sj.source_before->>'itemcode',t.destination_lot,sj.source_before->>'locationcode',l.quantity,
    sj.source_before,sj.source_after,tj.destination_before,tj.destination_after,'applied','inventory_reclass_move',
    jsonb_build_object('commandId',s.child_command,'requestId',s.child_request_id),
    lower(concat_ws(' ',actor_profile.username,sj.source_before->>'itemcode',sj.source_before->>'lotcode',
      sj.source_before->>'locationcode',t.destination_lot,t.destination_season))
  from pg_temp.reclass_batch_lines_v1 l join pg_temp.reclass_batch_sources_v1 s using(source_index)
  join pg_temp.reclass_batch_targets_v1 t using(source_index,destination_season)
  join pg_temp.reclass_batch_source_json_v1 sj using(source_index)
  join pg_temp.reclass_batch_target_json_v1 tj using(source_index,destination_season)
  order by s.source_index,l.line_index;

  select coalesce(jsonb_agg(jsonb_build_object('table','ph_master_inventory','row',r.row_value)
      order by r.source_index,r.row_order,r.destination_season),'[]'::jsonb) into result_rows
  from (select s.source_index,0 row_order,''::text destination_season,s.source_after row_value
      from pg_temp.reclass_batch_source_json_v1 s
    union all select t.source_index,1,t.destination_season,t.destination_after
      from pg_temp.reclass_batch_target_json_v1 t) r;
  select coalesce(jsonb_agg(jsonb_build_object('line',l.line_index,'direction',l.direction,
      'destinationSeason',l.destination_season,'quantity',l.quantity,'sourceUniqueId',s.source_uid,
      'destinationUniqueId',t.destination_uid,'sourceIndex',s.source_index) order by s.source_index,l.line_index),'[]'::jsonb)
    into result_movements
  from pg_temp.reclass_batch_lines_v1 l join pg_temp.reclass_batch_sources_v1 s using(source_index)
    join pg_temp.reclass_batch_targets_v1 t using(source_index,destination_season);

  select coalesce(jsonb_agg(s.child_request_id order by s.source_index),'[]'::jsonb) into child_ids
  from pg_temp.reclass_batch_sources_v1 s;
  perform set_config('gnc.row_actions_v3070',prior_action_context,true);
  select revision into current_revision from public.app_dataset_revisions where key='ph_master_inventory';
  update private.ph_inventory_reclass_commands_v1 c set result=jsonb_build_object('_batchResultReference',true,'batchRequestId',p_batch_request_id,'sourceIndex',s.source_index)
  from pg_temp.reclass_batch_sources_v1 s where c.request_id=s.child_request_id;
  update private.ph_inventory_reclass_batch_receipts_v1 set child_request_ids=(select array_agg(s.child_request_id order by s.source_index)
    from pg_temp.reclass_batch_sources_v1 s) where request_id=p_batch_request_id;
  return jsonb_build_object('ok',true,'commandId',p_command_id,'requestId',p_batch_request_id,'revision',current_revision,
    'seasonStocks',private.inventory_season_stock_receipt_v1(array(select distinct source_after->>'itemcode' from pg_temp.reclass_batch_source_json_v1)),
    'rows',result_rows,'movements',result_movements,'status','applied','importStatus','pending','_childRequestIds',child_ids);
end
$function$

CREATE OR REPLACE FUNCTION private.enqueue_drive_reclass_inquiry_v7_rep_impl(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_username text := lower(btrim(coalesce(p_payload->>'actorUsername','')));
  token text := btrim(coalesce(p_payload->>'idempotencyToken',p_payload->>'idempotency_token',''));
  source_mode text := lower(btrim(coalesce(p_payload #>> '{sourceContext,sourceMode}','drive')));
  event_key_value text;
  fingerprint text;
  projected jsonb;
  prepared jsonb;
  v6_payload jsonb;
  v5_payload jsonb;
  v3_payload jsonb;
  trio_result jsonb;
  field_result jsonb;
  underlying jsonb;
  event_row public.ph_request_delivery_outbox;
  actor_profile public.profiles;
  recipients text[] := '{}'::text[];
  current_live jsonb;
  final_payload jsonb;
  live_rows jsonb := '[]'::jsonb;
  live_uid text;
  live_uids text[] := '{}'::text[];
  row_value public.ph_master_inventory;
  inventory_revision bigint;
  existing_fingerprint text;
  source_itemcode text;
  source_row public.ph_master_inventory;
  v6_live_scope jsonb := '{}'::jsonb;
  request_fingerprint text;
  old_tx jsonb;
begin
  if actor_username='' or length(token)<12 or length(token)>180 then
    raise exception using errcode='22023',message='DRIVE_RECLASS_TOKEN_INVALID';
  end if;
  projected:=private.project_reclass_editable_fields_v7(p_payload);
  if source_mode not in ('drive','item-inquiry','eval-report-2') then
    raise exception using errcode='22023',message='DRIVE_RECLASS_V7_SOURCE_MODE_INVALID';
  end if;
  fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('workflowPolicyVersion',projected->>'workflowPolicyVersion','source',projected->'source','sourceContext',projected->'sourceContext','recipientPolicy','reclass-dylan-megan-submitter-v1','transaction',projected->'transaction','rowOverlays',projected->'rowOverlays')::text,'UTF8'),'sha256'),'hex');
  event_key_value:='reclass-inquiry:'||left(encode(extensions.digest(token,'sha256'),'hex'),40);
  perform pg_advisory_xact_lock(hashtextextended(event_key_value,0));
  select o.* into event_row from public.ph_request_delivery_outbox o
  where o.event_key=event_key_value and o.event_type='reclass_inquiry' for update;
  if event_row.event_id is not null then
    if lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}','')))<>actor_username then
      raise exception using errcode='42501',message='DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
    end if;
    select p.* into actor_profile from public.profiles p where lower(btrim(p.username))=actor_username
      and p.disabled_at is null and (p.locked_until is null or p.locked_until<=now()) and not p.must_change_password limit 1;
    if actor_profile.id is null then raise exception using errcode='42501',message='DRIVE_RECLASS_PROFILE_NOT_ACTIVE'; end if;
    if event_row.payload #>> '{reclassPayload,workflowPolicyVersion}'<>'reclass-action-workflow-v7-editable-fields-20261009'
       or event_row.payload #>> '{reclassPayload,protectedDelivery,requestFingerprint}' is distinct from fingerprint then
      raise exception using errcode='P0001',message='DRIVE_RECLASS_TOKEN_CONFLICT';
    end if;
    return private.drive_reclass_delivery_result_v1(event_row) || jsonb_build_object(
      'duplicate',true,
      'liveEdits',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,liveEdits}','[]'::jsonb),
      'inventoryRevision',event_row.payload #>> '{reclassPayload,protectedDelivery,inventoryRevision}',
      'liveEditScope',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,liveEditScope}','{}'::jsonb),
      'inventoryFields',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,inventoryFields}','[]'::jsonb),
      'v7Scope',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,v7Scope}','{}'::jsonb)
    );
  end if;

  perform private.lock_ph_master_inventory_for_reclass_lkg_v1(true);
  prepared:=private.prepare_reclass_editable_fields_v7(projected,actor_username);
  v6_payload:=prepared->'v6Payload';
  v5_payload:=prepared->'v5Payload';
  source_itemcode:=upper(btrim(coalesce(projected #>> '{source,itemcode}','')));
  select m.* into source_row from public.ph_master_inventory m
  where m.unique_id=btrim(coalesce(projected #>> '{source,unique_id}',projected #>> '{source,uniqueId}',''));
  if source_row.unique_id is null or source_itemcode='' or upper(btrim(coalesce(source_row.itemcode,'')))<>source_itemcode then
    raise exception using errcode='PT409',message='DRIVE_RECLASS_V7_SOURCE_CHANGED';
  end if;
  if source_mode='eval-report-2' then
    if lower(btrim(coalesce(projected #>> '{sourceContext,itemcode}','')))<>source_itemcode or not private.eval_report2_item_qualifies_v1(projected #>> '{sourceContext,reportId}',source_itemcode,now()) then raise exception using errcode='42501',message='DRIVE_RECLASS_V7_REPORT_SCOPE_FORBIDDEN'; end if;
  elsif source_mode='item-inquiry' and actor_username not in ('dylan_collyge','jd_jones','megan_kelly') then
    raise exception using errcode='42501',message='DRIVE_RECLASS_V7_ITEM_INQUIRY_FORBIDDEN';
  end if;
  recipients:=private.reclass_delivery_recipients_v1(actor_username);

  if coalesce((prepared->'v6Prepared'->'edits') is not null,false) then
    underlying:=public.enqueue_drive_reclass_inquiry_v6(v6_payload);
  elsif cardinality(array(select jsonb_array_elements_text(v5_payload #> '{transaction,requestActions}')))>0 then
    underlying:=public.enqueue_drive_reclass_inquiry_v5(v5_payload);
  else
    v3_payload:=v5_payload || jsonb_build_object(
      'workflowPolicyVersion','reclass-action-workflow-v3-row-actions-20260826',
      'transaction',(v5_payload->'transaction')||jsonb_build_object('requestActions','[]'::jsonb,'holdStopProposals','[]'::jsonb),
      'rowOverlays',(select coalesce(jsonb_agg(
        (value - 'proposals') || jsonb_build_object('proposals','[]'::jsonb,'expected',
          (value->'expected') - 'ptronhand' - 'desigitem' || jsonb_build_object(
            'ptronhand',value #>> '{expected,ptronhand}','desigitem',value #>> '{expected,desigitem}'))
        order by ordinality),'[]'::jsonb) from jsonb_array_elements(v5_payload->'rowOverlays') with ordinality a(value,ordinality))
    );
    underlying:=public.enqueue_drive_reclass_inquiry_v1(v3_payload || jsonb_build_object('actorUsername',actor_username,'idempotencyToken',token));
  end if;
  select o.* into event_row from public.ph_request_delivery_outbox o
  where o.event_key=event_key_value and o.event_type='reclass_inquiry' for update;
  if event_row.event_id is null or lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}','')))<>actor_username then
    raise exception using errcode='42501',message='DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
  end if;
  if coalesce(underlying->>'duplicate','false')='true' then raise exception using errcode='P0001',message='DRIVE_RECLASS_TOKEN_CONFLICT'; end if;

  trio_result:=coalesce(underlying,'{}'::jsonb);
  field_result:=private.apply_reclass_editable_fields_v7(prepared->'fieldRows',actor_username,prepared->>'stampTime');
  prepared:=jsonb_set(prepared,'{v7FrozenRows}',(select coalesce(jsonb_agg(f.value||jsonb_build_object('s_lts',m.s_lts,'season_oh',m.season_oh)),'[]') from jsonb_array_elements(prepared->'v7FrozenRows') f join public.ph_master_inventory m on m.unique_id=f.value->>'unique_id'));
  select r.revision into inventory_revision from public.app_dataset_revisions r where r.key='ph_master_inventory';
  if inventory_revision is null then raise exception using errcode='55000',message='RECLASS_V7_INVENTORY_REVISION_MISSING'; end if;
  select coalesce(array_agg(distinct x order by x),'{}'::text[]) into live_uids
  from (
    select value->>'unique_id' x from jsonb_array_elements(coalesce(trio_result->'liveEdits','[]'::jsonb))
    union select value->>'unique_id' from jsonb_array_elements(coalesce(field_result->'inventoryFields','[]'::jsonb))
  ) all_ids where nullif(x,'') is not null;
  for live_uid in select unnest(live_uids) loop
    select m.* into row_value from public.ph_master_inventory m where m.unique_id=live_uid;
    if row_value.unique_id is null then raise exception using errcode='PT409',message='DRIVE_RECLASS_V7_ROW_MISSING'; end if;
    live_rows:=live_rows||jsonb_build_array(jsonb_build_object(
      'unique_id',row_value.unique_id,'priority',row_value.priority,'holdstopcode',row_value.holdstopcode,
      'holdstopreason',row_value.holdstopreason,'av_rule_last_clear_reason',row_value.av_rule_last_clear_reason,
      'av_rule_last_cleared_at',row_value.av_rule_last_cleared_at,'last_updated',row_value.last_updated,
      'evidence',jsonb_build_object(
        'unique_id',row_value.unique_id,'itemcode',row_value.itemcode,'locationcode',row_value.locationcode,'lotcode',row_value.lotcode,
        'last_updated',row_value.last_updated,'photo_link',row_value.photo_link,'photo_name',row_value.photo_name,
        'match',row_value.match,'spec',row_value.spec,'caliper',row_value.caliper,'initial_ptr',row_value.initial_ptr,
        'loc_match_qty',row_value.loc_match_qty,'ptravailable',row_value.ptravailable,'av_note',row_value.av_note,
        'pic_note',row_value.pic_note,'sales_note',row_value.sales_note,'date_completed',row_value.date_completed,
        'app_tab_assignment',row_value.app_tab_assignment,'av_rule_av_note_updated_at',row_value.av_rule_av_note_updated_at,
        'av_rule_bundle_updated_at',row_value.av_rule_bundle_updated_at,'av_rule_caliper_updated_at',row_value.av_rule_caliper_updated_at,
        'av_rule_holdstop_snapshot',row_value.av_rule_holdstop_snapshot,'av_rule_last_clear_reason',row_value.av_rule_last_clear_reason,
        'av_rule_last_cleared_at',row_value.av_rule_last_cleared_at,'av_rule_match_updated_at',row_value.av_rule_match_updated_at,
        'av_rule_photo_updated_at',row_value.av_rule_photo_updated_at,'av_rule_priority_snapshot',row_value.av_rule_priority_snapshot,
        'av_rule_spec_updated_at',row_value.av_rule_spec_updated_at
      )
    ));
  end loop;

  update public.ph_request_delivery_outbox o set payload=jsonb_set(o.payload,'{reclassPayload}',(o.payload->'reclassPayload')||jsonb_build_object('sourceContext',projected->'sourceContext','recipientEmails',to_jsonb(recipients),'emailRecipients',to_jsonb(recipients),'recipients',(select coalesce(jsonb_agg(jsonb_build_object('email',email,'role','reclass_delivery') order by email),'[]'::jsonb) from unnest(recipients) email))) where o.event_id=event_row.event_id returning * into event_row;
  final_payload:=jsonb_set(event_row.payload,'{reclassPayload}',
    (event_row.payload->'reclassPayload')||jsonb_build_object(
      'workflowPolicyVersion','reclass-action-workflow-v7-editable-fields-20261009',
      'sourceContext',coalesce(projected->'sourceContext',jsonb_build_object('sourceMode','drive')),
      'transaction',projected->'transaction','rowOverlays',projected->'rowOverlays',
      'protectedDelivery',(coalesce(event_row.payload #> '{reclassPayload,protectedDelivery}','{}'::jsonb))||jsonb_build_object(
        'contractVersion','drive-reclass-protected-v1','requestFingerprint',fingerprint,
        'v7FrozenRows',prepared->'v7FrozenRows','liveEdits',live_rows,
        'inventoryFields',field_result->'inventoryFields','inventoryRevision',inventory_revision::text,
        'liveEditScope',coalesce(trio_result->'liveEditScope','{}'::jsonb),
        'v7Scope',jsonb_build_object('sourceMode',source_mode,'reportStamps',prepared->'reportStamps',
          'reportId',case when source_mode='eval-report-2' then projected #>> '{sourceContext,reportId}' else null end,
          'itemcode',source_itemcode)
      )
    ),false);
  if octet_length(convert_to(final_payload::text,'UTF8'))>4*1024*1024 then
    raise exception using errcode='22023',message='DRIVE_RECLASS_V7_PAYLOAD_TOO_LARGE';
  end if;
  update public.ph_request_delivery_outbox o set payload=final_payload,updated_at=clock_timestamp()
  where o.event_id=event_row.event_id returning * into event_row;
  update public.ph_inventory_transactions t set raw_payload=jsonb_build_object(
    'workflowPolicyVersion',event_row.payload #>> '{reclassPayload,workflowPolicyVersion}',
    'transaction',event_row.payload #> '{reclassPayload,transaction}',
    'rowOverlays',event_row.payload #> '{reclassPayload,rowOverlays}',
    'protectedDelivery',event_row.payload #> '{reclassPayload,protectedDelivery}'
  ) where t.delivery_event_id=event_row.event_id and t.status='requested' and t.event_type='inventory_change_request';
  if not found then raise exception using errcode='55000',message='DRIVE_RECLASS_V7_REQUESTED_AUDIT_MISSING'; end if;
  perform private.clear_current_ph_inventory_reclass_lkg_context_v1();
  return private.drive_reclass_delivery_result_v1(event_row)||jsonb_build_object(
    'duplicate',false,'seasonStocks',private.inventory_season_stock_receipt_v1(array[source_itemcode]),'liveEdits',live_rows,'inventoryFields',field_result->'inventoryFields',
    'inventoryRevision',inventory_revision::text,'liveEditScope',coalesce(trio_result->'liveEditScope','{}'::jsonb),
    'v7Scope',final_payload #> '{reclassPayload,protectedDelivery,v7Scope}'
  );
end
$function$

CREATE OR REPLACE FUNCTION private.require_reclass_explanations_v303(p_actor_id uuid, p_map jsonb, p_uids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.profiles%rowtype; uid text; exempt boolean;
begin
 select * into actor from public.profiles where id=p_actor_id and disabled_at is null
   and not must_change_password and (locked_until is null or locked_until<=now());
 if actor.id is null then raise exception using errcode='42501',message='DRIVE_RECLASS_PROFILE_NOT_ACTIVE'; end if;
 if jsonb_typeof(p_map) is distinct from 'object' or exists(select 1 from jsonb_each(p_map) e where jsonb_typeof(e.value)<>'string' or length(e.value#>>'{}')>4000) then
   raise exception using errcode='22023',message='DRIVE_RECLASS_EXPLANATION_INVALID'; end if;
 exempt:=regexp_replace(lower(btrim(coalesce(actor.role,''))),'[_\s]+','-','g') in ('admin','super-admin') or lower(btrim(actor.username))='dylan_collyge';
 foreach uid in array coalesce(p_uids,array[]::text[]) loop
   if not exempt and nullif(btrim(p_map->>uid),'') is null then
     raise exception using errcode='22023',message='DRIVE_RECLASS_EXPLANATION_REQUIRED';
   end if;
 end loop;
 perform set_config('gnc.reclass_explanations',p_map::text,true);
end $function$

CREATE OR REPLACE FUNCTION public.apply_inventory_reclass_move_v1(p_actor_id uuid, p_command_id text, p_expected_revision bigint, p_source_uid text, p_source_identity jsonb, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '5s'
 SET lock_timeout TO '2s'
AS $function$
declare prior_action_context text:=coalesce(current_setting('gnc.row_actions_v3070',true),'');

  actor_profile public.profiles%rowtype;
  source_row public.ph_master_inventory%rowtype;
  source_json jsonb;
  source_after_json jsonb;
  destination_row public.ph_master_inventory%rowtype;
  destination_json jsonb;
  destination_after_json jsonb;
  command_row private.ph_inventory_reclass_commands_v1%rowtype;
  source_on_hand numeric;
  source_available numeric;
  total_quantity numeric := 0;
  destination_quantity numeric;
  destination_on_hand numeric;
  destination_available numeric;
  current_revision bigint;
  line jsonb;
  line_index integer := 0;
  line_quantity numeric;
  destination_season text;
  quantity_field text;
  source_season text;
  source_suffix text;
  source_stem text;
  destination_lot text;
  destination_count integer;
  v_destination_uid text;
  v_destination_lineage text;
  source_lineage text;
  actor_username text;
  is_manager boolean;
  assigned_to_actor boolean;
  target_row jsonb;
  target_payload jsonb;
  safe_fields text[] := array[
    'itemcode','commonname','contsize','locationcode','source','warehousei','warehouseid','season',
    'qualitycode','field_tag_color','fieldtagcolor','s_lts','plantgroupcode','listprice','itemspec',
    'desigitem','desigcust','desigloc','priority','saleyear','blockalpha','blocknumber','bay',
    'grower','si_lts','a_lts','ai_lts','varietycode','genusname','botanicalname','reversecommon',
    'sortnamevariety','containersort','nationalaccount','salesrepid','salesrepname','printedcontainercode','photo_url','photo_link','photo_name','photos','photo_date','photo_expires_at',
    'date_completed','spec','caliper','loc_match_pct','loc_match_qty','loc_photo_match','match',
    'initial_photo_match_qty','pic_note','av_note','sales_note'
  ];
  zero_quantity_fields text[] := array[
    'ptronhand','ptravailable','ptrreviewed','season_supply','season_oh','season_demand','season_available',
    'ext_ptronhand','end_cap_qty','loc_match_qty','initial_ptr','largeptrqty','maxorderquantity'
  ];
  request_value jsonb;
  movements_value jsonb := '[]'::jsonb;
  rows_value jsonb := '[]'::jsonb;
  audit_id text;
  actor_role text;
  permission_scope text;
  destination_aggregates record;
  before_source_on_hand numeric;
  before_source_available numeric;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'INVENTORY_RECLASS_FORBIDDEN';
  end if;
  if p_actor_id is null or p_expected_revision is null or p_expected_revision < 1
     or p_command_id is null or p_command_id !~ '^[A-Za-z0-9:_.-]{12,180}$'
     or p_source_uid is null or length(p_source_uid) > 1000
     or jsonb_typeof(p_source_identity) is distinct from 'object'
     or jsonb_typeof(p_lines) is distinct from 'array'
     or jsonb_array_length(p_lines) < 1 or jsonb_array_length(p_lines) > 100 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_PAYLOAD_INVALID';
  end if;
  select * into actor_profile from public.profiles p
  where p.id = p_actor_id and p.disabled_at is null
    and (p.locked_until is null or p.locked_until <= now()) and not p.must_change_password;
  if actor_profile.id is null then
    raise exception using errcode = '42501', message = 'INVENTORY_RECLASS_PROFILE_INACTIVE';
  end if;
  actor_role := CASE WHEN private.inventory_unrestricted_actor_v23155(actor_profile) THEN 'ADMIN' ELSE private.normalized_profile_role(actor_profile.role) END;
  actor_username := lower(btrim(coalesce(actor_profile.username,'')));
  is_manager := actor_role in ('ADMIN','ADMINISTRATOR','MANAGER');
  if actor_role not in ('ADMIN','ADMINISTRATOR','MANAGER','EVAL','EVALUATOR') and actor_role not like '%EVAL%' then
    raise exception using errcode = '42501', message = 'INVENTORY_RECLASS_FORBIDDEN';
  end if;
  select e.access_scope into permission_scope
  from private.get_effective_app_permissions_v1(actor_profile.id,private.resolve_app_access_policy_id_v1(false)) e
  where e.permission_key = 'drive.reclass.submit' and e.allowed limit 1;
  if permission_scope is null and not private.inventory_unrestricted_actor_v23155(actor_profile) and actor_role not in ('EVAL','EVALUATOR') then
    raise exception using errcode = '42501', message = 'INVENTORY_RECLASS_PERMISSION_REQUIRED';
  end if;

  request_value := jsonb_build_object('expectedRevision',p_expected_revision,'sourceUid',p_source_uid,
    'sourceIdentity',p_source_identity,'lines',p_lines);
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text || ':' || p_command_id,0));
  select * into command_row from private.ph_inventory_reclass_commands_v1 c
  where c.actor_id = p_actor_id and c.command_id = p_command_id for update;
  if found then
    if command_row.request is distinct from request_value then
      raise exception using errcode='PT409', message = 'INVENTORY_RECLASS_COMMAND_CONFLICT';
    end if;
    if command_row.result->>'_batchResultReference' = 'true' then
      return private.replay_inventory_reclass_batch_child_v1(command_row.request_id);
    end if;
    return command_row.result;
  end if;

  current_revision := private.lock_ph_master_inventory_for_reclass_lkg_v1(true);
  if current_revision is distinct from p_expected_revision then
    NULL; /* agdata308_reclass_lww: retain current locked row */
  end if;
  select * into source_row from public.ph_master_inventory m
  where m.unique_id = p_source_uid for update;
  if source_row.unique_id is null then
    raise exception using errcode='PT409', message = 'INVENTORY_RECLASS_SOURCE_MISSING';
  end if;
  if not is_manager then
    select private.inventory_row_assigned_to_actor_v2392(actor_username,source_row.unique_id,source_row.itemcode) into assigned_to_actor;
    if not assigned_to_actor then raise exception using errcode='42501',message='DRIVE_RECLASS_ROW_NOT_ASSIGNED'; end if;
  end if;
  source_json := to_jsonb(source_row);
  source_lineage := private.ph_master_inventory_lineage_key_v1(source_json);
  if p_source_identity - array['unique_id','itemcode','contsize','locationcode','lotcode','season','ptronhand','ptravailable']
       <> '{}'::jsonb
     or p_source_identity->>'unique_id' is distinct from source_row.unique_id
     or p_source_identity->>'itemcode' is distinct from source_row.itemcode
     or p_source_identity->>'contsize' is distinct from source_row.contsize
     or p_source_identity->>'locationcode' is distinct from source_row.locationcode
     or p_source_identity->>'lotcode' is distinct from source_row.lotcode
     or p_source_identity->>'season' is distinct from source_row.season
     or p_source_identity->>'ptronhand' is distinct from source_row.ptronhand
     or p_source_identity->>'ptravailable' is distinct from source_row.ptravailable then
    raise exception using errcode='PT409', message = 'INVENTORY_RECLASS_SOURCE_CHANGED';
  end if;
  if (select count(*) from public.ph_master_inventory m
      where coalesce(m.warehouseid,m.warehousei,'') = coalesce(source_row.warehouseid,source_row.warehousei,'')
        and coalesce(m.itemcode,'') = coalesce(source_row.itemcode,'')
        and coalesce(m.contsize,'') = coalesce(source_row.contsize,'')
        and coalesce(m.locationcode,'') = coalesce(source_row.locationcode,'')
        and coalesce(m.lotcode,'') = coalesce(source_row.lotcode,'')
        and coalesce(m.source,'') = coalesce(source_row.source,'')
        and coalesce(m.desigitem,'') = coalesce(source_row.desigitem,'')
        and coalesce(m.desigcust,'') = coalesce(source_row.desigcust,'')
        and coalesce(m.desigloc,'') = coalesce(source_row.desigloc,'')) <> 1 then
    raise exception using errcode='PT409', message = 'INVENTORY_RECLASS_SOURCE_AMBIGUOUS';
  end if;
  source_on_hand := private.reclass_numeric_v1(source_row.ptronhand);
  source_available := private.reclass_numeric_v1(source_row.ptravailable);
  if source_on_hand is null or source_available is null then
    raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_QUANTITY_UNKNOWN';
  end if;
  before_source_on_hand := source_on_hand;
  before_source_available := source_available;
  source_season := upper(btrim(coalesce(nullif(source_row.season,''),nullif(regexp_replace(coalesce(source_row.lotcode,''),'^.*[.]',''),''),'')));
  if source_row.lotcode !~ '^.+[.](F1|S1|U1|U2|U3|X|Y|Z)$' then
    raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_LOT_INVALID';
  end if;
  source_suffix := upper(substring(source_row.lotcode from '[.]([^.]+)$'));
  if source_suffix is distinct from source_season then
    raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_LOT_SEASON_AMBIGUOUS';
  end if;
  source_stem := regexp_replace(source_row.lotcode,'[.][^.]+$','');

  for line in select value from jsonb_array_elements(p_lines) loop
    line_index := line_index + 1;
    if jsonb_typeof(line) is distinct from 'object'
       or line - array['direction','destinationSeason','quantity'] <> '{}'::jsonb
       or not (line ?& array['direction','destinationSeason','quantity'])
       or jsonb_typeof(line->'direction') <> 'string'
       or jsonb_typeof(line->'destinationSeason') <> 'string'
       or jsonb_typeof(line->'quantity') <> 'number'
       or line->>'direction' not in ('move_up','move_down') then
      raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_LINE_INVALID';
    end if;
    destination_season := upper(btrim(line->>'destinationSeason'));
    if destination_season not in ('F1','S1','U1','U2','U3','X','Y','Z') or destination_season = source_season then
      raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_DESTINATION_INVALID';
    end if;
    line_quantity := (line->>'quantity')::numeric;
    if line_quantity < 1 or line_quantity <> trunc(line_quantity) or line_quantity > 2147483647 then
      raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_QUANTITY_INVALID';
    end if;
    total_quantity := total_quantity + line_quantity;
  end loop;
  if total_quantity > source_on_hand or total_quantity > source_available then
    raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_QUANTITY_UNDERFLOW';
  end if;
  source_after_json := source_json || jsonb_build_object(
    'ptronhand',(source_on_hand-total_quantity)::text,
    'ptravailable',(source_available-total_quantity)::text,
    'last_updated',clock_timestamp()
  );

  create temporary table if not exists reclass_move_targets_v1 (
    destination_season text primary key,
    destination_lot text not null,
    quantity numeric not null,
    destination_uid text,
    destination_lineage text,
    destination_before jsonb,
    destination_after jsonb
  ) on commit drop;
  truncate table pg_temp.reclass_move_targets_v1;
  insert into pg_temp.reclass_move_targets_v1(destination_season,destination_lot,quantity)
  select upper(btrim(value->>'destinationSeason')), source_stem || '.' || upper(btrim(value->>'destinationSeason')),
    sum((value->>'quantity')::numeric)
  from jsonb_array_elements(p_lines)
  group by upper(btrim(value->>'destinationSeason'));

  for destination_aggregates in select target.* from pg_temp.reclass_move_targets_v1 target order by target.destination_lot loop
    select count(*), min(m.unique_id) into destination_count,v_destination_uid
    from public.ph_master_inventory m
    where coalesce(m.warehouseid,m.warehousei,'') = coalesce(source_row.warehouseid,source_row.warehousei,'')
      and coalesce(m.itemcode,'') = coalesce(source_row.itemcode,'')
      and coalesce(m.contsize,'') = coalesce(source_row.contsize,'')
      and coalesce(m.locationcode,'') = coalesce(source_row.locationcode,'')
      and coalesce(m.lotcode,'') = destination_aggregates.destination_lot
      and coalesce(m.source,'') = coalesce(source_row.source,'')
      and coalesce(m.desigitem,'') = coalesce(source_row.desigitem,'')
      and coalesce(m.desigcust,'') = coalesce(source_row.desigcust,'')
      and coalesce(m.desigloc,'') = coalesce(source_row.desigloc,'');
    if destination_count > 1 then
      raise exception using errcode='PT409', message = 'INVENTORY_RECLASS_DESTINATION_AMBIGUOUS';
    end if;
    if destination_count = 1 then
      select * into destination_row from public.ph_master_inventory m
      where m.unique_id = v_destination_uid for update;
      if upper(btrim(coalesce(destination_row.season,''))) is distinct from destination_aggregates.destination_season then
        raise exception using errcode='PT409', message = 'INVENTORY_RECLASS_DESTINATION_SEASON_MISMATCH';
      end if;
      destination_json := to_jsonb(destination_row);
      destination_on_hand := private.reclass_numeric_v1(destination_row.ptronhand);
      destination_available := private.reclass_numeric_v1(destination_row.ptravailable);
      if destination_on_hand is null or destination_available is null then
        raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_DESTINATION_QUANTITY_UNKNOWN';
      end if;
      destination_after_json := destination_json || jsonb_build_object(
        'ptronhand',(destination_on_hand+destination_aggregates.quantity)::text,
        'ptravailable',(destination_available+destination_aggregates.quantity)::text,
        'last_updated',clock_timestamp()
      );
    else
      v_destination_uid := gen_random_uuid()::text;
      select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb) into target_payload
      from jsonb_each(source_json) e
      where e.key = any(safe_fields);
      target_payload := target_payload || jsonb_build_object(
        'unique_id',v_destination_uid,'lotcode',destination_aggregates.destination_lot,
        'season',destination_aggregates.destination_season,'last_updated',clock_timestamp()
      );
      foreach quantity_field in array zero_quantity_fields loop target_payload := jsonb_set(target_payload,array[quantity_field],to_jsonb('0'::text),true); end loop;
      target_payload := target_payload || jsonb_build_object(
        'ptronhand',destination_aggregates.quantity::text,
        'ptravailable',destination_aggregates.quantity::text
      );
      target_payload := target_payload || jsonb_build_object(
        'concat','reclass-move:' || encode(extensions.digest(convert_to(p_command_id || ':' || v_destination_uid,'UTF8'),'sha256'),'hex')
      );
      destination_json := null;
      destination_after_json := target_payload;
    end if;
    v_destination_lineage := private.ph_master_inventory_lineage_key_v1(destination_after_json);
    update pg_temp.reclass_move_targets_v1 as target set destination_uid=v_destination_uid,
      destination_lineage=v_destination_lineage,destination_before=destination_json,destination_after=destination_after_json
    where target.destination_season=destination_aggregates.destination_season;
    total_quantity := 0; -- reset below to the validated full request quantity after per-target records are prepared.
  end loop;
  select coalesce(sum((value->>'quantity')::numeric),0) into total_quantity from jsonb_array_elements(p_lines);
  source_after_json := source_json || jsonb_build_object(
    'ptronhand',(before_source_on_hand-total_quantity)::text,
    'ptravailable',(before_source_available-total_quantity)::text,
    'last_updated',clock_timestamp()
  );
  perform set_config('gnc.row_actions_v3070',private.action_move_map_v3070((select jsonb_agg(jsonb_build_object(
    'from_uid',p_source_uid,'from_lot',source_row.lotcode,'from_location',source_row.locationcode,
    'to_uid',t.destination_uid,'to_lot',t.destination_lot,'to_location',source_row.locationcode,
    'direction',l->>'direction','quantity',l->'quantity')) from jsonb_array_elements(p_lines) l
    join pg_temp.reclass_move_targets_v1 t on t.destination_season=upper(btrim(l->>'destinationSeason'))),p_actor_id,p_command_id),true);
  update public.ph_master_inventory m set
    ptronhand=(before_source_on_hand-total_quantity)::text,
    ptravailable=(before_source_available-total_quantity)::text,
    last_updated=clock_timestamp()
  where m.unique_id=p_source_uid returning to_jsonb(m.*) into source_after_json;

  insert into private.ph_inventory_reclass_commands_v1(actor_id,command_id,request,result)
  values(p_actor_id,p_command_id,request_value,'{}'::jsonb) returning * into command_row;
  for destination_aggregates in select target.* from pg_temp.reclass_move_targets_v1 target order by target.destination_lot loop
    if destination_aggregates.destination_before is null then
      insert into public.ph_master_inventory
      select populated_destination.*
      from jsonb_populate_record(null::public.ph_master_inventory,destination_aggregates.destination_after) as populated_destination;
      select to_jsonb(m.*) into destination_after_json from public.ph_master_inventory m
      where m.unique_id=destination_aggregates.destination_uid;
    else
      update public.ph_master_inventory m set
        ptronhand=destination_aggregates.destination_after->>'ptronhand',
        ptravailable=destination_aggregates.destination_after->>'ptravailable',
        last_updated=clock_timestamp()
      where m.unique_id=destination_aggregates.destination_uid returning to_jsonb(m.*) into destination_after_json;
    end if;
    insert into private.ph_inventory_reclass_import_aliases_v1(lineage_key,canonical_unique_id,request_id)
    values(destination_aggregates.destination_lineage,destination_aggregates.destination_uid,command_row.request_id)
    on conflict(lineage_key) do update set canonical_unique_id=excluded.canonical_unique_id,request_id=excluded.request_id
    where private.ph_inventory_reclass_import_aliases_v1.canonical_unique_id=excluded.canonical_unique_id;
    if not found then raise exception using errcode='PT409',message='INVENTORY_RECLASS_DESTINATION_AMBIGUOUS'; end if;
    insert into private.ph_inventory_reclass_movements_v1(
      request_id,line_index,direction,destination_season,quantity,source_unique_id,destination_unique_id,
      source_lineage_key,destination_lineage_key,source_identity,destination_identity,
      source_before,source_after,destination_before,destination_after
    )
    select command_row.request_id,ordinality::integer,value->>'direction',destination_aggregates.destination_season,
      (value->>'quantity')::numeric,p_source_uid,destination_aggregates.destination_uid,source_lineage,destination_aggregates.destination_lineage,
      jsonb_build_object('unique_id',p_source_uid,'itemcode',source_row.itemcode,'contsize',source_row.contsize,
        'locationcode',source_row.locationcode,'lotcode',source_row.lotcode,'season',source_row.season,
        'source',source_row.source,'warehouseid',coalesce(source_row.warehouseid,source_row.warehousei),
        'desigitem',source_row.desigitem,'desigcust',source_row.desigcust,'desigloc',source_row.desigloc),
      jsonb_build_object('unique_id',destination_aggregates.destination_uid,'itemcode',source_row.itemcode,
        'contsize',source_row.contsize,'locationcode',source_row.locationcode,'lotcode',destination_aggregates.destination_lot,
        'season',destination_aggregates.destination_season,'source',source_row.source,
        'warehouseid',coalesce(source_row.warehouseid,source_row.warehousei),'desigitem',source_row.desigitem,
        'desigcust',source_row.desigcust,'desigloc',source_row.desigloc),
      source_json,source_after_json,destination_aggregates.destination_before,destination_after_json
    from jsonb_array_elements(p_lines) with ordinality as line_rows(value,ordinality)
    where upper(btrim(value->>'destinationSeason'))=destination_aggregates.destination_season;

    select to_jsonb(m.*) into destination_after_json from public.ph_master_inventory m
    where m.unique_id=destination_aggregates.destination_uid;
    rows_value := rows_value || jsonb_build_array(jsonb_build_object('table','ph_master_inventory','row',destination_after_json));
    movements_value := movements_value || (
      select coalesce(jsonb_agg(jsonb_build_object('line',ordinality,'direction',value->>'direction',
        'destinationSeason',upper(btrim(value->>'destinationSeason')),'quantity',(value->>'quantity')::numeric,
        'sourceUniqueId',p_source_uid,'destinationUniqueId',destination_aggregates.destination_uid)
        order by ordinality),'[]'::jsonb)
      from jsonb_array_elements(p_lines) with ordinality as line_rows(value,ordinality)
      where upper(btrim(value->>'destinationSeason'))=destination_aggregates.destination_season
    );
    for line in select value from jsonb_array_elements(p_lines) where upper(btrim(value->>'destinationSeason'))=destination_aggregates.destination_season loop
      audit_id := gen_random_uuid()::text;
      insert into public.ph_inventory_transactions(
        unique_id,action,actor_id,actor_username,actor_display,source_table,source_unique_id,destination_table,destination_unique_id,
        source_itemcode,source_lotcode,source_locationcode,destination_itemcode,destination_lotcode,destination_locationcode,
        quantity,source_before,source_after,destination_before,destination_after,status,event_type,raw_payload,search_text
      ) values(audit_id,line->>'direction',p_actor_id,actor_profile.username,coalesce(actor_profile.display_name,actor_profile.username),
        'ph_master_inventory',p_source_uid,'ph_master_inventory',destination_aggregates.destination_uid,
        source_row.itemcode,source_row.lotcode,source_row.locationcode,source_row.itemcode,destination_aggregates.destination_lot,
        source_row.locationcode,(line->>'quantity')::numeric,source_json,source_after_json,destination_aggregates.destination_before,
        destination_after_json,'applied','inventory_reclass_move',jsonb_build_object('commandId',p_command_id,'requestId',command_row.request_id),
        lower(concat_ws(' ',actor_profile.username,source_row.itemcode,source_row.lotcode,source_row.locationcode,
          destination_aggregates.destination_lot,destination_aggregates.destination_season)));
    end loop;
  end loop;
  select r.revision into current_revision from public.app_dataset_revisions r where r.key='ph_master_inventory';
  perform set_config('gnc.row_actions_v3070',prior_action_context,true);
  rows_value := jsonb_build_array(jsonb_build_object('table','ph_master_inventory','row',source_after_json)) || rows_value;
  request_value := jsonb_build_object('ok',true,'commandId',p_command_id,'requestId',command_row.request_id,'revision',current_revision,
    'rows',rows_value,'movements',movements_value,'status','applied','importStatus','pending');
  update private.ph_inventory_reclass_commands_v1 set result=request_value where request_id=command_row.request_id;
  perform private.clear_current_ph_inventory_reclass_lkg_context_v1();
  return request_value;
end
$function$

CREATE OR REPLACE FUNCTION public.apply_inventory_reclass_moves_v1(p_actor_id uuid, p_command_id text, p_expected_revision bigint, p_moves jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '10s'
 SET lock_timeout TO '2s'
AS $function$
declare
  actor_profile public.profiles%rowtype;
  batch_row private.ph_inventory_reclass_batch_receipts_v1%rowtype;
  actor_role text;
  permission_scope text;
  request_value jsonb;
  line_count integer:=0;
  current_revision bigint;
  child_ids uuid[]:='{}'::uuid[];
  result_value jsonb;
  previous_reclass_marker text;
begin
  if coalesce(auth.role(),'') <> 'service_role' then raise exception using errcode='42501',message='INVENTORY_RECLASS_FORBIDDEN'; end if;
  if p_actor_id is null or p_expected_revision is null or p_expected_revision < 0
    or p_command_id is null or p_command_id !~ '^[A-Za-z0-9:_.-]{12,180}$'
    or jsonb_typeof(p_moves) is distinct from 'array' or jsonb_array_length(p_moves)<1 or jsonb_array_length(p_moves)>100 then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_PAYLOAD_INVALID';
  end if;
  select * into actor_profile from public.profiles p where p.id=p_actor_id and p.disabled_at is null
    and (p.locked_until is null or p.locked_until<=now()) and not p.must_change_password;
  if actor_profile.id is null then raise exception using errcode='42501',message='INVENTORY_RECLASS_PROFILE_INACTIVE'; end if;
  actor_role := CASE WHEN private.inventory_unrestricted_actor_v23155(actor_profile) THEN 'ADMIN' ELSE private.normalized_profile_role(actor_profile.role) END;
  if actor_role not in ('ADMIN','ADMINISTRATOR','MANAGER','EVAL','EVALUATOR') and actor_role not like '%EVAL%' then
    raise exception using errcode='42501',message='INVENTORY_RECLASS_FORBIDDEN';
  end if;
  select e.access_scope into permission_scope from private.get_effective_app_permissions_v1(actor_profile.id,private.resolve_app_access_policy_id_v1(false)) e
    where e.permission_key='drive.reclass.submit' and e.allowed limit 1;
  if permission_scope is null and not private.inventory_unrestricted_actor_v23155(actor_profile) and actor_role not in ('EVAL','EVALUATOR') then raise exception using errcode='42501',message='INVENTORY_RECLASS_PERMISSION_REQUIRED'; end if;
  request_value:=jsonb_build_object('expectedRevision',p_expected_revision,'moves',p_moves);
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||':'||p_command_id,0));
  select * into batch_row from private.ph_inventory_reclass_batch_receipts_v1 b
    where b.actor_id=p_actor_id and b.command_id=p_command_id for update;
  if found then
    if batch_row.request is distinct from request_value then raise exception using errcode='PT409',message='INVENTORY_RECLASS_COMMAND_CONFLICT'; end if;
    return batch_row.result;
  end if;
  current_revision:=private.lock_ph_master_inventory_for_reclass_lkg_v1(true);
  perform current_revision;

  if exists(select 1 from jsonb_array_elements(p_moves) e(value)
    where jsonb_typeof(value) is distinct from 'object' or value - array['source','lines'] <> '{}'::jsonb
      or not (value ?& array['source','lines']) or jsonb_typeof(value->'source') is distinct from 'object'
      or jsonb_typeof(value->'lines') is distinct from 'array' or jsonb_array_length(value->'lines')<1) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_MOVE_INVALID';
  end if;
  if exists(select 1 from jsonb_array_elements(p_moves) e(value)
    where btrim(coalesce(value#>>'{source,uniqueId}',''))='' or length(value#>>'{source,uniqueId}')>1000
      or jsonb_typeof(value#>'{source,identity}') is distinct from 'object') then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_SOURCE_INVALID';
  end if;
  if exists(select 1 from jsonb_array_elements(p_moves) e(value) group by value #>> '{source,uniqueId}' having count(*)>1) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_OVERLAP_INVALID';
  end if;
  select sum(jsonb_array_length(value->'lines'))::integer into line_count from jsonb_array_elements(p_moves) e(value);
  if line_count>100 then raise exception using errcode='22023',message='INVENTORY_RECLASS_LINES_INVALID'; end if;
  if exists(select 1 from jsonb_array_elements(p_moves) e(value)
    cross join lateral jsonb_array_elements(value->'lines') l(line)
    where jsonb_typeof(line) is distinct from 'object'
      or line-array['direction','destinationSeason','quantity']<>'{}'::jsonb
      or not (line ?& array['direction','destinationSeason','quantity'])
      or jsonb_typeof(line->'direction') is distinct from 'string'
      or jsonb_typeof(line->'destinationSeason') is distinct from 'string'
      or jsonb_typeof(line->'quantity') is distinct from 'number'
      or line->>'direction' not in ('move_up','move_down')) then
    raise exception using errcode='22023',message='INVENTORY_RECLASS_LINE_INVALID';
  end if;
  insert into private.ph_inventory_reclass_batch_receipts_v1(actor_id,command_id,request)
    values(p_actor_id,p_command_id,request_value) returning * into batch_row;
  previous_reclass_marker:=current_setting('gnc.inventory_reclass_batch',true);
  update private.ph_inventory_reclass_batch_receipts_v1 set backend_pid=pg_backend_pid(),transaction_id=txid_current()
    where request_id=batch_row.request_id;
  perform set_config('gnc.inventory_reclass_batch',batch_row.request_id::text,true);
  result_value:=private.apply_inventory_reclass_moves_set_v1(p_actor_id,p_command_id,p_expected_revision,p_moves,batch_row.request_id);
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into child_ids
    from jsonb_array_elements_text(result_value->'_childRequestIds') e(value);
  result_value:=result_value-'_childRequestIds';
  perform set_config('gnc.inventory_reclass_batch',coalesce(previous_reclass_marker,''),true);
  update private.ph_inventory_reclass_batch_receipts_v1 set backend_pid=null,transaction_id=null,
    child_request_ids=child_ids,result=result_value
    where request_id=batch_row.request_id;
  perform private.clear_current_ph_inventory_reclass_lkg_context_v1();
  return result_value;
end
$function$

CREATE OR REPLACE FUNCTION public.apply_inventory_reclass_moves_with_delivery_v1(p_actor_id uuid, p_command_id text, p_expected_revision bigint DEFAULT NULL::bigint, p_moves jsonb DEFAULT NULL::jsonb, p_receipt_encoding text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '15s'
 SET lock_timeout TO '2s'
AS $function$
declare
  batch_receipt private.ph_inventory_reclass_batch_receipts_v1%rowtype;
  actor_profile public.profiles%rowtype;
  result_value jsonb;
  event_row public.ph_request_delivery_outbox%rowtype;
  event_key_value text;
  actor_username text;
  actor_email text;
  recipient_emails text[];
  applied_rows jsonb;
  report_rows jsonb;
  row_overlays jsonb;
  report_stamps jsonb;
  reclass_payload jsonb;
  report_source jsonb;
  request_actions jsonb;
  is_test_command boolean := coalesce(p_command_id like 'test:%',false);
  moves_value jsonb;
  child_ids uuid[];
  move_request_id uuid;
  existing_command boolean := false;
  resolved_revision bigint;
  previous_edit_actor text:=coalesce(current_setting('gnc.inventory_edit_actor',true),'');
begin
  if not private.is_service_role_request() then
    raise exception using errcode = '42501', message = 'INVENTORY_RECLASS_FORBIDDEN';
  end if;
  if p_actor_id is null or p_command_id is null or p_command_id !~ '^[A-Za-z0-9:_.-]{12,180}$'

    or (p_expected_revision is not null and p_expected_revision < 0)
    or jsonb_typeof(p_moves) is distinct from 'array' or jsonb_array_length(p_moves) < 1
    or jsonb_array_length(p_moves) > 100
    or (p_receipt_encoding is not null and p_receipt_encoding <> 'master-null-elision-v1') then
    raise exception using errcode = '22023', message = 'INVENTORY_RECLASS_PAYLOAD_INVALID';
  end if;

  if is_test_command then
    select * into actor_profile from public.profiles p where p.id=p_actor_id and p.disabled_at is null
      and (p.locked_until is null or p.locked_until<=now()) and not p.must_change_password;
    if actor_profile.id is null or private.normalized_profile_role(actor_profile.role) not in ('ADMIN','ADMINISTRATOR') then
      raise exception using errcode='42501',message='INVENTORY_RECLASS_TEST_ADMIN_REQUIRED';
    end if;
  end if;

  perform private.require_reclass_explanations_v303(p_actor_id,
    coalesce((select jsonb_object_agg(value#>>'{source,uniqueId}',coalesce(value->>'reclass_explanation','')) from jsonb_array_elements(p_moves)),'{}'::jsonb),
    array(select value#>>'{source,uniqueId}' from jsonb_array_elements(p_moves)));
  p_moves:=(select jsonb_agg(value-'reclass_explanation' order by n) from jsonb_array_elements(p_moves) with ordinality e(value,n));
  -- Match the movement RPC's actor/command lock so receipt lookup, movement,
  -- and event insertion cannot race a retry of the same command.
  perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text || ':' || p_command_id, 0));
  select * into batch_receipt from private.ph_inventory_reclass_batch_receipts_v1 b
    where b.actor_id = p_actor_id and b.command_id = p_command_id for update;
  existing_command := found;
  if existing_command then
    resolved_revision := (batch_receipt.request->>'expectedRevision')::bigint;
  else
    resolved_revision := private.lock_ph_master_inventory_for_reclass_lkg_v1();
  end if;

  perform set_config('gnc.inventory_edit_actor',p_actor_id::text,true);
  -- v2380_pre_edit_report_rows: captured from physical ERP rows before any mutation.
  if not existing_command then
    perform 1 from public.ph_master_inventory m
      where upper(btrim(m.itemcode)) in (
        select upper(btrim(coalesce(move->'source'->'identity'->>'itemcode',move->'source'->>'itemcode')))
        from jsonb_array_elements(p_moves) move
      ) order by m.unique_id for update;
    select coalesce(jsonb_agg(to_jsonb(m) order by m.locationcode,m.lotcode,m.unique_id),'[]'::jsonb)
      into report_rows
    from public.ph_master_inventory m
    where upper(btrim(m.itemcode)) in (
      select upper(btrim(coalesce(move->'source'->'identity'->>'itemcode',move->'source'->>'itemcode')))
      from jsonb_array_elements(p_moves) move
    )
      and coalesce(m.concat,'') not like 'reclass-move:%'
      and not exists (
        select 1 from private.ph_inventory_reclass_movements_v1 prior_move
        where prior_move.destination_unique_id=m.unique_id and prior_move.destination_before is null
      );
  end if;

  if p_receipt_encoding = 'master-null-elision-v1' then
    result_value := public.apply_inventory_reclass_moves_compact_v1(p_actor_id, p_command_id, resolved_revision, p_moves);
  else
    result_value := public.apply_inventory_reclass_moves_v1(p_actor_id, p_command_id, resolved_revision, p_moves);
  end if;

  perform set_config('gnc.inventory_edit_actor',previous_edit_actor,true);
  -- A command created before this delivery contract is not retroactively
  -- emailed. Newly applied commands always have their outbox intent below.
  if existing_command then
    event_key_value := 'inventory-reclass-move-completed:' || p_actor_id::text || ':' || p_command_id;
    select * into event_row from public.ph_request_delivery_outbox o
      where o.event_key = event_key_value and o.event_type = 'reclass_inquiry';
    return result_value || jsonb_build_object('duplicate', true, 'emailQueued', case when is_test_command then false else event_row.event_id is not null end,
      'deliveryEventId', event_row.event_id) || case when is_test_command then jsonb_build_object('testDeliverySuppressed',true) else '{}'::jsonb end;
  end if;

  if is_test_command then
    return result_value || jsonb_build_object('duplicate',false,'emailQueued',false,
      'testDeliverySuppressed',true,'reportRows',report_rows);
  end if;

  if coalesce(result_value->>'status', '') <> 'applied' then
    return result_value;
  end if;

  select * into actor_profile from public.profiles p where p.id = p_actor_id and p.disabled_at is null
    and (p.locked_until is null or p.locked_until <= now()) and not p.must_change_password;
  if actor_profile.id is null then raise exception using errcode = '42501', message = 'INVENTORY_RECLASS_PROFILE_INACTIVE'; end if;
  actor_username := lower(btrim(actor_profile.username));
  select lower(btrim(u.email)) into actor_email from auth.users u
    where u.id = p_actor_id and u.email_confirmed_at is not null
      and btrim(coalesce(u.email, '')) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$';
  if actor_email is null then raise exception using errcode = 'P0001', message = 'INVENTORY_RECLASS_MOVE_ACTOR_EMAIL_UNAVAILABLE'; end if;

  -- Resolve the server-owned Dylan + Megan + active actor policy; never trust
  -- any recipient address from the request payload.
  recipient_emails := private.reclass_delivery_recipients_v1(actor_username);
  if actor_email <> all(recipient_emails) then raise exception using errcode='P0001',message='INVENTORY_RECLASS_REQUIRED_RECIPIENT_POLICY_INVALID'; end if;

  move_request_id := nullif(result_value->>'requestId', '')::uuid;
  if move_request_id is null then raise exception using errcode = 'P0001', message = 'INVENTORY_RECLASS_MOVE_RECEIPT_MISSING'; end if;
  select b.child_request_ids, b.result->'rows' into child_ids, applied_rows from private.ph_inventory_reclass_batch_receipts_v1 b
    where b.actor_id = p_actor_id and b.command_id = p_command_id and b.request_id = move_request_id;
  if child_ids is null or jsonb_typeof(applied_rows) is distinct from 'array' or jsonb_array_length(applied_rows) < 1 then
    raise exception using errcode = 'P0001', message = 'INVENTORY_RECLASS_MOVE_RECEIPT_MISSING';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'direction', m.direction,
      'destinationSeason', m.destination_season,
      'quantity', m.quantity,
      'remainingSourceQuantity', m.source_after->>'ptronhand',
      'newTargetQuantity', m.destination_after->>'ptronhand',
      'botanicalname', m.source_before->>'botanicalname',
      'reclass_explanation', m.reclass_explanation,
      'submittedAt', statement_timestamp(),
      'source', jsonb_build_object('unique_id',m.source_unique_id,'itemcode', m.source_identity->>'itemcode',
        'commonname', coalesce(m.source_before->>'commonname', ''),
        'contsize', m.source_identity->>'contsize', 'locationcode', m.source_identity->>'locationcode',
        'lotcode', m.source_identity->>'lotcode', 'season', m.source_identity->>'season'),
      'destination', jsonb_build_object('unique_id',m.destination_unique_id,'itemcode', m.destination_identity->>'itemcode',
        'commonname', coalesce(m.source_before->>'commonname', ''),
        'contsize', m.destination_identity->>'contsize', 'locationcode', m.destination_identity->>'locationcode',
        'lotcode', m.destination_identity->>'lotcode', 'season', m.destination_identity->>'season')
    ) order by m.request_id, m.line_index), '[]'::jsonb)
    into moves_value from private.ph_inventory_reclass_movements_v1 m where m.request_id = any(child_ids);
    if jsonb_array_length(moves_value) < 1 then raise exception using errcode = 'P0001', message = 'INVENTORY_RECLASS_MOVE_RECEIPT_MISSING'; end if;
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'unique_id',row_value->>'unique_id',
      'expected',jsonb_build_object('itemcode',row_value->>'itemcode','lotcode',row_value->>'lotcode',
        'locationcode',row_value->>'locationcode','ptronhand',row_value->>'ptronhand',
        'priority',row_value->>'priority','ptravailable',row_value->>'ptravailable','desigitem',row_value->>'desigitem'),
      'proposals',coalesce((select jsonb_agg(jsonb_build_object('action',move_group.direction,
        'splits',move_group.splits,'applyHold',false,'holdReason','') order by move_group.direction)
        from (select move->>'direction' direction,
          jsonb_agg(jsonb_build_object('quantity',move->>'quantity','destinationSeason',move->>'destinationSeason')
            order by move->>'destinationSeason') splits
          from jsonb_array_elements(moves_value) move
          where move #>> '{source,unique_id}'=row_value->>'unique_id'
          group by move->>'direction') move_group),'[]'::jsonb)
    ) || case when synthetic.note is null then '{}'::jsonb else jsonb_build_object(
      'temporaryValues',jsonb_build_object('locationnote',concat_ws(E'\n',nullif(btrim(row_value->>'locationnote'),''),synthetic.note)),
      'temporaryChangedFields','["locationnote"]'::jsonb) end
      order by row_value->>'locationcode',row_value->>'lotcode',row_value->>'unique_id'),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('unique_id',row_value->>'unique_id','stamps',jsonb_build_object(
      'prisetby',row_value->'prisetby','priupdated',row_value->'priupdated',
      'locationnotedate',row_value->'locationnotedate','evaldate',row_value->'evaldate'))
      order by row_value->>'locationcode',row_value->>'lotcode',row_value->>'unique_id'),'[]'::jsonb)
    into row_overlays,report_stamps from jsonb_array_elements(report_rows) row_value
    left join lateral (
      select string_agg(case when movement->>'direction'='move_down' then 'DOWN ' else 'UP ' end
        ||coalesce(movement->>'quantity','')||' FROM '||coalesce(movement #>> '{source,lotcode}','')
        ||' TO '||coalesce(movement #>> '{destination,season}','')||' (AgData-created lot at '
        ||coalesce(movement #>> '{source,locationcode}','')||')','; ' order by movement->>'direction') note
      from jsonb_array_elements(moves_value) movement
      where movement #>> '{source,unique_id}'<>row_value->>'unique_id'
        and exists (
          with recursive ancestry(unique_id,depth,path) as (
            select movement #>> '{source,unique_id}',0,array[movement #>> '{source,unique_id}']
            union all
            select prior_move.source_unique_id::text,ancestry.depth+1,ancestry.path||prior_move.source_unique_id::text
            from ancestry join private.ph_inventory_reclass_movements_v1 prior_move
              on prior_move.destination_unique_id::text=ancestry.unique_id and prior_move.destination_before is null
            where ancestry.depth<32 and not prior_move.source_unique_id::text=any(ancestry.path)
          ) select 1 from ancestry where ancestry.unique_id=row_value->>'unique_id'
        )
    ) synthetic on true;
  select coalesce(jsonb_agg(to_jsonb(direction) order by direction),'[]'::jsonb) into request_actions
    from (select distinct move->>'direction' direction from jsonb_array_elements(moves_value) move
      where exists(select 1 from jsonb_array_elements(report_rows) row_value
        where row_value->>'unique_id'=move #>> '{source,unique_id}')) actions;
  with recursive ancestry(unique_id,depth,path) as (
    select moves_value #>> '{0,source,unique_id}',0,array[moves_value #>> '{0,source,unique_id}']
    union all
    select prior_move.source_unique_id::text,ancestry.depth+1,ancestry.path||prior_move.source_unique_id::text
    from ancestry join private.ph_inventory_reclass_movements_v1 prior_move
      on prior_move.destination_unique_id::text=ancestry.unique_id and prior_move.destination_before is null
    where ancestry.depth<32 and not prior_move.source_unique_id::text=any(ancestry.path)
  )
  select row_value into report_source from ancestry join lateral jsonb_array_elements(report_rows) row_value
    on row_value->>'unique_id'=ancestry.unique_id order by ancestry.depth desc limit 1;
  if report_source is null then
    select row_value into report_source from jsonb_array_elements(report_rows) row_value
      where upper(btrim(row_value->>'itemcode'))=upper(btrim(moves_value #>> '{0,source,itemcode}'))
      order by row_value->>'locationcode',row_value->>'lotcode',row_value->>'unique_id' limit 1;
  end if;
  if report_source is null or jsonb_array_length(row_overlays)<>jsonb_array_length(report_rows)
    or jsonb_array_length(report_stamps)<>jsonb_array_length(report_rows) then
    raise exception using errcode='P0001',message='INVENTORY_RECLASS_V7_REPORT_SNAPSHOT_INVALID';
  end if;
  reclass_payload:=jsonb_build_object(
    'actor',jsonb_build_object('username',actor_username,'displayName',coalesce(nullif(btrim(actor_profile.display_name),''),actor_username)),
    'actorUsername',actor_username,'actorDisplayName',coalesce(nullif(btrim(actor_profile.display_name),''),actor_username),
    'actorEmail',actor_email,'source',jsonb_build_object('unique_id',report_source->>'unique_id',
      'itemcode',report_source->>'itemcode','contsize',report_source->>'contsize',
      'locationcode',report_source->>'locationcode','lotcode',report_source->>'lotcode',
      'season',report_source->>'season','ptronhand',report_source->>'ptronhand',
      'ptravailable',report_source->>'ptravailable','desigitem',report_source->>'desigitem'),
    'workflowPolicyVersion','reclass-action-workflow-v7-editable-fields-20261009',
    'sourceContext',jsonb_build_object('sourceMode','drive'),
    'transaction',jsonb_build_object('requestActions',request_actions,'holdStopProposals','[]'::jsonb,'scope','{}'::jsonb),
    'rowOverlays',row_overlays,'recipientEmails',to_jsonb(recipient_emails),
    'protectedDelivery',jsonb_build_object('contractVersion','drive-reclass-protected-v1',
      'requestFingerprint',encode(extensions.digest(convert_to(p_actor_id::text||':'||p_command_id,'UTF8'),'sha256'),'hex'),
      'v7FrozenRows',report_rows,'liveEdits','[]'::jsonb,'inventoryFields','[]'::jsonb,
      'inventoryRevision',result_value->>'revision','v7Scope',jsonb_build_object('sourceMode','drive',
        'reportStamps',report_stamps,'itemcode',upper(btrim(report_source->>'itemcode'))))
  );


  -- Freeze all item siblings for the report, including other lot years.
  select jsonb_agg(jsonb_build_object('table','ph_master_inventory','row',to_jsonb(m)) order by m.locationcode,m.lotcode,m.unique_id) into applied_rows
   from public.ph_master_inventory m where m.itemcode in (select r->'row'->>'itemcode' from jsonb_array_elements(applied_rows) r);
  event_key_value := 'inventory-reclass-move-completed:' || p_actor_id::text || ':' || p_command_id;
  insert into public.ph_request_delivery_outbox(event_key, event_type, request_id, payload, status, next_attempt_at)
    values(event_key_value, 'reclass_inquiry', move_request_id::text,
      jsonb_build_object('contractVersion', 'inventory-reclass-move-completed-v1',
        'submittedAt', moves_value->0->'submittedAt',
        'commandId', p_command_id, 'requestId', move_request_id, 'actorProfileId', p_actor_id,
        'actorUsername', actor_username, 'actorDisplayName', coalesce(nullif(btrim(actor_profile.display_name), ''), actor_username),
        'actorEmail', actor_email, 'revision',result_value->>'revision','commandId',p_command_id,'requestId',move_request_id,'actorProfileId',p_actor_id,'actorUsername',actor_username,'actorEmail',actor_email,'actorDisplayName',coalesce(nullif(btrim(actor_profile.display_name),''),actor_username),'reclassPayload',reclass_payload,'moves',moves_value,'appliedRows',applied_rows,'report_rows',report_rows,'deliveryRecipients',to_jsonb(recipient_emails)),
      'pending', now()) returning * into event_row;

  return result_value || jsonb_build_object('duplicate', false, 'emailQueued', true, 'deliveryEventId', event_row.event_id) || case when is_test_command then jsonb_build_object('testDeliverySuppressed',true) else '{}'::jsonb end;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_drive_reclass_inquiry_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor public.profiles;
  actor_username text := lower(btrim(coalesce(p_payload->>'actorUsername', '')));
  actor_role text;
  access_scope text;
  source_uid text := btrim(coalesce(p_payload #>> '{source,unique_id}', p_payload #>> '{source,uniqueId}', ''));
  source_row public.ph_master_inventory;
  source_json jsonb;
  token text := btrim(coalesce(p_payload->>'idempotencyToken', p_payload->>'idempotency_token', ''));
  event_key_value text;
  event_row public.ph_request_delivery_outbox;
  is_manager boolean := false;
  is_evaluator boolean := false;
  assigned_to_actor boolean := false;
  required_usernames text[];
  recipient_emails text[] := '{}'::text[];
  unavailable_usernames text[] := '{}'::text[];
  safe_payload jsonb;
begin
  if auth.role() is distinct from 'service_role' then raise exception using errcode='42501',message='DRIVE_RECLASS_FORBIDDEN'; end if;
  perform private.require_reclass_explanations_v303(
    (select id from public.profiles where lower(btrim(username))=lower(btrim(p_payload->>'actorUsername'))),
    coalesce(p_payload->'reclassExplanations',nullif(current_setting('gnc.reclass_explanations',true),'')::jsonb,'{}'::jsonb),
    coalesce((select array_agg(distinct uid) from (
      select value->>'unique_id' uid from jsonb_array_elements(coalesce(p_payload->'rowOverlays','[]'::jsonb))
        where jsonb_array_length(coalesce(value->'proposals','[]'::jsonb))>0 or jsonb_array_length(coalesce(value->'fieldEdits','[]'::jsonb))>0
          or value->>'resolution'='done' or value#>>'{action,included}'='true'
      union select value->>'sourceUid' from jsonb_array_elements(coalesce(p_payload#>'{transaction,holdStopProposals}','[]'::jsonb))
    ) targets where uid is not null),array[p_payload#>>'{source,unique_id}']));
  p_payload:=p_payload-'reclassExplanations';
  if jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_PAYLOAD_INVALID';
  end if;
  if actor_username = '' then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_ACTOR_REQUIRED';
  end if;
  select p.* into actor
  from public.profiles p
  where lower(btrim(p.username)) = actor_username
    and p.disabled_at is null
    and (p.locked_until is null or p.locked_until <= now())
    and not p.must_change_password
  limit 1;
  if actor.id is null then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PROFILE_NOT_ACTIVE';
  end if;

  actor_role := private.normalized_profile_role(actor.role);
  is_manager := actor_role in ('ADMIN', 'ADMINISTRATOR', 'MANAGER');
  is_evaluator := actor_role in ('EVAL', 'EVALUATOR') or actor_role like '%EVAL%';
  if not is_manager and not is_evaluator and not private.sales_rep_operation_scope_v1(actor.id) then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_FORBIDDEN';
  end if;

  select e.access_scope into access_scope
  from private.get_effective_app_permissions_v1(
    actor.id,
    private.resolve_app_access_policy_id_v1(false)
  ) e
  where e.permission_key = 'drive.reclass.submit'
    and e.allowed
  limit 1;
  if access_scope is null and private.sales_rep_operation_scope_v1(actor.id) then access_scope:='global'; end if; if access_scope is null then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PERMISSION_REQUIRED';
  end if;

  if coalesce(p_payload->>'workflowPolicyVersion', '') <> 'reclass-action-workflow-v3-row-actions-20260826' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_V3_REQUIRED';
  end if;
  if length(token) < 12 or length(token) > 180 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_TOKEN_INVALID';
  end if;
  if source_uid = '' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_SOURCE_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_payload->'transaction', '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_payload->'rowOverlays', '[]'::jsonb)) <> 'array' then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_ACTIONS_INVALID';
  end if;

  select m.* into source_row
  from public.ph_master_inventory m
  where btrim(coalesce(m.unique_id, '')) = source_uid
  limit 1
  for share;
  if source_row.unique_id is null then
    raise exception using errcode='PT409', message = 'DRIVE_RECLASS_SOURCE_MISSING';
  end if;
  source_json := to_jsonb(source_row);
  if nullif(btrim(coalesce(p_payload #>> '{source,itemcode}', '')), '') is not null
     and upper(btrim(p_payload #>> '{source,itemcode}')) <> upper(btrim(coalesce(source_row.itemcode, ''))) then
    raise exception using errcode='PT409', message = 'DRIVE_RECLASS_SOURCE_CHANGED';
  end if;
  if nullif(btrim(coalesce(p_payload #>> '{source,lotcode}', '')), '') is not null
     and upper(btrim(p_payload #>> '{source,lotcode}')) <> upper(btrim(coalesce(source_json->>'lotcode', ''))) then
    raise exception using errcode='PT409', message = 'DRIVE_RECLASS_SOURCE_CHANGED';
  end if;
  if nullif(btrim(coalesce(p_payload #>> '{source,locationcode}', '')), '') is not null
     and upper(btrim(p_payload #>> '{source,locationcode}')) <> upper(btrim(coalesce(source_json->>'locationcode', ''))) then
    raise exception using errcode='PT409', message = 'DRIVE_RECLASS_SOURCE_CHANGED';
  end if;

  if is_evaluator and not is_manager then
    select private.inventory_effective_owner_v1(source_uid) is not null
      and lower(regexp_replace(btrim(private.inventory_effective_owner_v1(source_uid)), '[^a-z0-9]+', '_', 'g')) = actor_username
      and not exists (
        select 1 from jsonb_array_elements(coalesce(p_payload->'rowOverlays', '[]'::jsonb)) overlay
        where nullif(btrim(coalesce(overlay->>'unique_id', '')), '') is null
          or lower(regexp_replace(btrim(coalesce(private.inventory_effective_owner_v1(overlay->>'unique_id'), '')), '[^a-z0-9]+', '_', 'g')) is distinct from actor_username
      )
    into assigned_to_actor;
    if not assigned_to_actor then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_ROW_NOT_ASSIGNED';
    end if;
  end if;

  required_usernames := array['dylan_collyge', 'megan_kelly', 'sharon_combs', actor_username];
  with wanted as (
    select lower(btrim(value)) as username, min(ordinality) as ordinal
    from unnest(required_usernames) with ordinality entry(value, ordinality)
    where btrim(coalesce(value, '')) <> ''
    group by lower(btrim(value))
  ), resolved as (
    select w.username, w.ordinal, lower(btrim(u.email)) as email
    from wanted w
    join public.profiles p on lower(btrim(p.username)) = w.username
    join auth.users u on u.id = p.id
    where p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now())
      and not p.must_change_password
      and u.email_confirmed_at is not null
      and btrim(coalesce(u.email, '')) ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
  )
  select
    coalesce(array_agg(distinct r.email order by r.email) filter (where r.email is not null), '{}'::text[]),
    coalesce(array_agg(w.username order by w.ordinal) filter (where r.username is null), '{}'::text[])
  into recipient_emails, unavailable_usernames
  from wanted w
  left join resolved r on r.username = w.username;

  if cardinality(recipient_emails) = 0 then
    raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_RECIPIENTS_UNAVAILABLE';
  end if;

  event_key_value := 'reclass-inquiry:' || left(encode(extensions.digest(token, 'sha256'), 'hex'), 40);
  perform pg_advisory_xact_lock(hashtextextended(event_key_value, 0));
  select o.* into event_row
  from public.ph_request_delivery_outbox o
  where o.event_key = event_key_value
    and o.event_type = 'reclass_inquiry'
  limit 1
  for update;
  if event_row.event_id is not null then
    if event_row.payload #>> '{reclassPayload,protectedDelivery,contractVersion}' <> 'drive-reclass-protected-v1' then
      raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_TOKEN_CONFLICT';
    end if;
    if lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}', ''))) <> actor_username then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
    end if;
    return private.drive_reclass_delivery_result_v1(event_row) || jsonb_build_object('duplicate', true);
  end if;

  safe_payload := jsonb_build_object(
    'type', 'reclass_inquiry_email',
    'action', 'reclass',
    'workflowPolicyVersion', 'reclass-action-workflow-v3-row-actions-20260826',
    'idempotencyToken', token,
    'actor', jsonb_build_object(
      'username', actor_username,
      'display', coalesce(nullif(btrim(actor.display_name), ''), actor.username),
      'role', actor.role
    ),
    'source', jsonb_build_object(
      'unique_id', source_row.unique_id,
      'source_table', 'ph_master_inventory',
      'itemcode', source_row.itemcode,
      'lotcode', source_json->>'lotcode',
      'locationcode', source_json->>'locationcode',
      'season', source_json->>'season',
      'saleyear', source_json->>'saleyear'
    ),
    'transaction', p_payload->'transaction',
    'rowOverlays', p_payload->'rowOverlays',
    'clientVersion', left(btrim(coalesce(p_payload->>'clientVersion', '')), 80),
    'sourceContext', jsonb_build_object('sourceMode', 'drive'),
    'recipientEmails', to_jsonb(recipient_emails),
    'emailRecipients', to_jsonb(recipient_emails),
    'recipients', (
      select coalesce(jsonb_agg(jsonb_build_object('email', email, 'role', 'required_drive_reclass') order by email), '[]'::jsonb)
      from unnest(recipient_emails) email
    ),
    'protectedDelivery', jsonb_build_object(
      'contractVersion', 'drive-reclass-protected-v1',
      'actorProfileId', actor.id,
      'unavailableUsernames', to_jsonb(unavailable_usernames)
    )
  );
  if octet_length(safe_payload::text) > 4 * 1024 * 1024 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_PAYLOAD_TOO_LARGE';
  end if;

  insert into public.ph_request_delivery_outbox
    (event_key, event_type, request_id, request_folder, payload, status, next_attempt_at)
  values
    (event_key_value, 'reclass_inquiry', null, null, jsonb_build_object('reclassPayload', safe_payload), 'pending', now())
  returning * into event_row;

  return private.drive_reclass_delivery_result_v1(event_row)
    || jsonb_build_object('duplicate', false, 'unavailableUsernames', to_jsonb(unavailable_usernames));
end
$function$

CREATE OR REPLACE FUNCTION public.enqueue_drive_reclass_inquiry_v4(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  legacy_envelope jsonb;
  result_value jsonb;
  event_row public.ph_request_delivery_outbox;
  actor_username text := lower(btrim(coalesce(p_payload->>'actorUsername','')));
  token text := btrim(coalesce(p_payload->>'idempotencyToken',p_payload->>'idempotency_token',''));
  event_key_value text;
  fingerprint text;
  saved_fingerprint text;
  final_payload jsonb;
  actor_profile public.profiles;
  actor_role text;
  access_scope text;
begin
  if auth.role() is distinct from 'service_role' then raise exception using errcode='42501',message='DRIVE_RECLASS_FORBIDDEN'; end if;
  perform private.require_reclass_explanations_v303(
    (select id from public.profiles where lower(btrim(username))=lower(btrim(p_payload->>'actorUsername'))),
    coalesce(p_payload->'reclassExplanations',nullif(current_setting('gnc.reclass_explanations',true),'')::jsonb,'{}'::jsonb),
    coalesce((select array_agg(distinct uid) from (
      select value->>'unique_id' uid from jsonb_array_elements(coalesce(p_payload->'rowOverlays','[]'::jsonb))
        where jsonb_array_length(coalesce(value->'proposals','[]'::jsonb))>0 or jsonb_array_length(coalesce(value->'fieldEdits','[]'::jsonb))>0
          or value->>'resolution'='done' or value#>>'{action,included}'='true'
      union select value->>'sourceUid' from jsonb_array_elements(coalesce(p_payload#>'{transaction,holdStopProposals}','[]'::jsonb))
    ) targets where uid is not null),array[p_payload#>>'{source,unique_id}']));
  p_payload:=p_payload-'reclassExplanations';
  if actor_username = '' or length(token) < 12 or length(token) > 180 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_TOKEN_INVALID';
  end if;
  perform private.project_reclass_split_move_v4(p_payload);
  fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'workflowPolicyVersion', p_payload->>'workflowPolicyVersion',
    'source', p_payload->'source', 'transaction', p_payload->'transaction', 'rowOverlays', p_payload->'rowOverlays'
  )::text,'UTF8'),'sha256'),'hex');
  event_key_value := 'reclass-inquiry:' || left(encode(extensions.digest(token,'sha256'),'hex'),40);
  perform pg_advisory_xact_lock(hashtextextended(event_key_value,0));
  select o.* into event_row from public.ph_request_delivery_outbox o
  where o.event_key = event_key_value and o.event_type = 'reclass_inquiry' for update;
  if event_row.event_id is not null then
    if lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}',''))) <> actor_username then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
    end if;
    select p.* into actor_profile from public.profiles p
    where lower(btrim(p.username)) = actor_username and p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now()) and not p.must_change_password limit 1;
    if actor_profile.id is null then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PROFILE_NOT_ACTIVE';
    end if;
    actor_role := private.normalized_profile_role(actor_profile.role);
    if actor_role not in ('ADMIN','ADMINISTRATOR','MANAGER','EVAL','EVALUATOR') and actor_role not like '%EVAL%' then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_FORBIDDEN';
    end if;
    select e.access_scope into access_scope
    from private.get_effective_app_permissions_v1(actor_profile.id, private.resolve_app_access_policy_id_v1(false)) e
    where e.permission_key = 'drive.reclass.submit' and e.allowed limit 1;
    if access_scope is null then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PERMISSION_REQUIRED';
    end if;
    saved_fingerprint := event_row.payload #>> '{reclassPayload,protectedDelivery,requestFingerprint}';
    if event_row.payload #>> '{reclassPayload,workflowPolicyVersion}' <> 'reclass-action-workflow-v4-split-moves-20261006'
       or saved_fingerprint is distinct from fingerprint then
      raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_TOKEN_CONFLICT';
    end if;
    return private.drive_reclass_delivery_result_v1(event_row) || jsonb_build_object('duplicate',true);
  end if;
  -- Reuse V1 authorization, recipients and its Requested audit INSERT trigger.
  -- Keep the original proposal data so that trigger records every split/hold.
  -- Only the compatibility envelope is V3: the final outbox becomes V4 below
  -- before this transaction commits. Any validation failure rolls both back.
  legacy_envelope := p_payload || jsonb_build_object(
    'workflowPolicyVersion','reclass-action-workflow-v3-row-actions-20260826',
    'actorUsername',actor_username,'idempotencyToken',token
  );
  result_value := public.enqueue_drive_reclass_inquiry_v1(legacy_envelope);
  select o.* into event_row from public.ph_request_delivery_outbox o
  where o.event_key = event_key_value and o.event_type = 'reclass_inquiry' for update;
  if event_row.event_id is null or lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}',''))) <> actor_username then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
  end if;
  if coalesce(result_value->>'duplicate','false') = 'true' then
    raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_TOKEN_CONFLICT';
  end if;
  perform private.validate_drive_reclass_split_move_v4(p_payload);
  final_payload := jsonb_set(event_row.payload, '{reclassPayload}',
      (event_row.payload->'reclassPayload') || jsonb_build_object(
        'workflowPolicyVersion','reclass-action-workflow-v4-split-moves-20261006',
        'transaction',p_payload->'transaction', 'rowOverlays',p_payload->'rowOverlays',
        'protectedDelivery',(event_row.payload->'reclassPayload'->'protectedDelivery') || jsonb_build_object('requestFingerprint',fingerprint)
      ), false);
  if octet_length(convert_to(final_payload::text,'UTF8')) > 4 * 1024 * 1024 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_V4_PAYLOAD_TOO_LARGE';
  end if;
  update public.ph_request_delivery_outbox o
  set payload = final_payload, updated_at = now()
  where o.event_id = event_row.event_id
  returning * into event_row;
  return private.drive_reclass_delivery_result_v1(event_row)
    || jsonb_build_object('duplicate',false,'unavailableUsernames',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,unavailableUsernames}','[]'::jsonb));
end
$function$

