    'source',projected->'source','transaction',projected->'transaction','rowOverlays',projected->'rowOverlays'
  )::text,'UTF8'),'sha256'),'hex');
  event_key_value := 'reclass-inquiry:' || left(encode(extensions.digest(token,'sha256'),'hex'),40);
  perform pg_advisory_xact_lock(hashtextextended(event_key_value,0));
  select o.* into event_row from public.ph_request_delivery_outbox o
  where o.event_key=event_key_value and o.event_type='reclass_inquiry' for update;
  if event_row.event_id is not null then
    if lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}',''))) <> actor_username then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
    end if;
    select p.* into actor_profile from public.profiles p
    where lower(btrim(p.username))=actor_username and p.disabled_at is null
      and (p.locked_until is null or p.locked_until <= now()) and not p.must_change_password limit 1;
    if actor_profile.id is null then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PROFILE_NOT_ACTIVE';
    end if;
    actor_role := private.normalized_profile_role(actor_profile.role);
    if actor_role not in ('ADMIN','ADMINISTRATOR','MANAGER','EVAL','EVALUATOR') and actor_role not like '%EVAL%' and not private.sales_rep_operation_scope_v1(actor_profile.id) then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_FORBIDDEN';
    end if;
    select e.access_scope into access_scope
    from private.get_effective_app_permissions_v1(actor_profile.id,private.resolve_app_access_policy_id_v1(false)) e
    where e.permission_key='drive.reclass.submit' and e.allowed limit 1;
    if access_scope is null and private.sales_rep_operation_scope_v1(actor_profile.id) then access_scope:='global'; end if; if access_scope is null then
      raise exception using errcode = '42501', message = 'DRIVE_RECLASS_PERMISSION_REQUIRED';
    end if;
    existing_fingerprint := event_row.payload #>> '{reclassPayload,protectedDelivery,requestFingerprint}';
    if event_row.payload #>> '{reclassPayload,workflowPolicyVersion}' <> 'reclass-action-workflow-v6-smart-shield-20261009'
       or existing_fingerprint is distinct from fingerprint then
      raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_TOKEN_CONFLICT';
    end if;
    return private.drive_reclass_delivery_result_v1(event_row) || jsonb_build_object(
      'duplicate',true,
      'liveEdits',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,liveEdits}','[]'::jsonb),
      'inventoryRevision',event_row.payload #>> '{reclassPayload,protectedDelivery,inventoryRevision}',
      'liveEditScope',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,liveEditScope}','{}'::jsonb),
      'unavailableUsernames',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,unavailableUsernames}','[]'::jsonb)
    );
  end if;

  -- Only a new token reads and validates mutable inventory state. Exact
  -- retries return the saved, authorized receipt above even after the live
  -- values have changed as part of the original submission.
  perform private.lock_ph_master_inventory_for_live_edit_v6();
  projected := private.validate_reclass_smart_shield_v6(p_payload);

  v5_payload := projected || jsonb_build_object(
    'workflowPolicyVersion','reclass-action-workflow-v5-sheared-20261008',
    'transaction',(projected->'transaction') || jsonb_build_object('holdStopProposals',coalesce((
      select jsonb_agg(value - 'sourceUid') from jsonb_array_elements(coalesce(projected #> '{transaction,holdStopProposals}','[]'::jsonb))
    ),'[]'::jsonb)),
    'rowOverlays',(select coalesce(jsonb_agg(
      (value - 'expected') || jsonb_build_object('expected',(value->'expected') - 'priority' - 'holdstopcode' - 'holdstopreason')
      order by ordinality
    ),'[]'::jsonb) from jsonb_array_elements(projected->'rowOverlays') with ordinality a(value,ordinality))
  );
  event_result := public.enqueue_drive_reclass_inquiry_v5(v5_payload);
  select o.* into event_row from public.ph_request_delivery_outbox o
  where o.event_key=event_key_value and o.event_type='reclass_inquiry' for update;
  if event_row.event_id is null or lower(btrim(coalesce(event_row.payload #>> '{reclassPayload,actor,username}',''))) <> actor_username then
    raise exception using errcode = '42501', message = 'DRIVE_RECLASS_TOKEN_OWNERSHIP_CONFLICT';
  end if;
  if coalesce(event_result->>'duplicate','false') = 'true' then
    raise exception using errcode = 'P0001', message = 'DRIVE_RECLASS_TOKEN_CONFLICT';
  end if;

  prepared := private.prepare_reclass_live_edits_v6(p_payload,actor_username);
  live_result := private.apply_ph_master_inventory_live_edits_v6(prepared->'edits');
  final_payload := jsonb_set(event_row.payload,'{reclassPayload}',
    (event_row.payload->'reclassPayload') || jsonb_build_object(
      'workflowPolicyVersion','reclass-action-workflow-v6-smart-shield-20261009',
      'transaction',projected->'transaction',
      'rowOverlays',projected->'rowOverlays',
      'protectedDelivery',(coalesce(event_row.payload #> '{reclassPayload,protectedDelivery}','{}'::jsonb)) || jsonb_build_object(
        'requestFingerprint',fingerprint,
        'v6FrozenRows',prepared->'v6FrozenRows',
        'liveEdits',live_result->'liveEdits',
        'inventoryRevision',live_result->'inventoryRevision',
        'liveEditScope',prepared->'liveEditScope'
      )
    ),false);
  if octet_length(convert_to(final_payload::text,'UTF8')) > 4 * 1024 * 1024 then
    raise exception using errcode = '22023', message = 'DRIVE_RECLASS_V6_PAYLOAD_TOO_LARGE';
  end if;
  update public.ph_request_delivery_outbox o set payload=final_payload,updated_at=clock_timestamp()
  where o.event_id=event_row.event_id returning * into event_row;
  update public.ph_inventory_transactions t set raw_payload=jsonb_build_object(
    'workflowPolicyVersion',event_row.payload #>> '{reclassPayload,workflowPolicyVersion}',
    'transaction',event_row.payload #> '{reclassPayload,transaction}',
    'rowOverlays',event_row.payload #> '{reclassPayload,rowOverlays}',
    'protectedDelivery',event_row.payload #> '{reclassPayload,protectedDelivery}'
  )
  where t.delivery_event_id=event_row.event_id
    and t.status='requested' and t.event_type='inventory_change_request';
  if not found then
    raise exception using errcode='55000',message='DRIVE_RECLASS_V6_REQUESTED_AUDIT_MISSING';
  end if;
  return private.drive_reclass_delivery_result_v1(event_row) || jsonb_build_object(
    'duplicate',false,
    'liveEdits',live_result->'liveEdits',
    'inventoryRevision',live_result->'inventoryRevision',
    'liveEditScope',prepared->'liveEditScope',
    'unavailableUsernames',coalesce(event_row.payload #> '{reclassPayload,protectedDelivery,unavailableUsernames}','[]'::jsonb)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.enqueue_drive_reclass_inquiry_v7(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.profiles; actor_count integer; projected jsonb; result jsonb;
  previous_edit_actor text:=coalesce(current_setting('gnc.inventory_edit_actor',true),'');
  previous_scope text:=coalesce(current_setting('gnc.sales_rep_operation_actor',true),'');
begin
  if auth.role() is distinct from 'service_role' then raise exception using errcode='42501',message='DRIVE_RECLASS_FORBIDDEN'; end if;
  perform private.require_reclass_explanations_v303(
    (select id from public.profiles where lower(btrim(username))=lower(btrim(p_payload->>'actorUsername'))),
    coalesce(p_payload->'reclassExplanations',nullif(current_setting('gnc.reclass_explanations',true),'')::jsonb,'{}'::jsonb),
    coalesce((select array_agg(distinct uid) from (
      select value->>'unique_id' uid from jsonb_array_elements(coalesce(p_payload->'rowOverlays','[]'::jsonb))
        where jsonb_array_length(coalesce(value->'proposals','[]'::jsonb))>0 or jsonb_array_length(coalesce(value->'fieldEdits','[]'::jsonb))>0
          or value->>'resolution'='done' or value#>>'{action,included}'='true'
      union select value->>'sourceUid' from jsonb_array_elements(coalesce(p_payload#>'{transaction,holdStopProposals}','[]'::jsonb))
    ) targets where uid is not null),array[p_payload#>>'{source,unique_id}']));
  p_payload:=p_payload-'reclassExplanations';
  if auth.role() is distinct from 'service_role' then
    raise exception using errcode='42501',message='DRIVE_RECLASS_FORBIDDEN';
  end if;
  select count(*) into actor_count from public.profiles p
    where lower(btrim(p.username))=lower(btrim(coalesce(p_payload->>'actorUsername','')));
  select p.* into actor from public.profiles p
    where lower(btrim(p.username))=lower(btrim(coalesce(p_payload->>'actorUsername','')));
  if actor_count<>1 or actor.disabled_at is not null or actor.must_change_password
    or actor.locked_until>now() then
    raise exception using errcode='42501',message='DRIVE_RECLASS_PROFILE_NOT_ACTIVE';
  end if;
  if upper(btrim(actor.role,E' \t\n\r')) in ('REP','SALESREP','SALES') then
    if not private.navigation_module_allowed_v1(actor.id,'drive') or exists (
      select 1 from private.app_access_user_overrides o
      where o.policy_id=private.resolve_app_access_policy_id_v1(false) and o.profile_id=actor.id
        and o.permission_key='drive.reclass.submit' and not o.allowed
    ) then
      raise exception using errcode='42501',message='DRIVE_RECLASS_FORBIDDEN';
    end if;
    projected:=private.project_reclass_editable_fields_v7(p_payload);
    if coalesce(projected#>>'{sourceContext,sourceMode}','drive')<>'drive'
      or jsonb_array_length(projected#>'{transaction,requestActions}')=0
      or exists(select 1 from jsonb_array_elements_text(projected#>'{transaction,requestActions}') a(value)
        where value not in ('priority_change','hold','take_off_hold','stop_ship','off_stop_ship'))
      or exists(select 1 from jsonb_array_elements(projected->'rowOverlays') r(value)
        where jsonb_array_length(coalesce(value->'fieldEdits','[]'::jsonb))>0)
    then raise exception using errcode='42501',message='SALES_REP_OPERATION_FORBIDDEN'; end if;
    perform set_config('gnc.sales_rep_operation_actor',actor.id::text,true);
  else
    perform set_config('gnc.sales_rep_operation_actor','',true);
  end if;
  perform set_config('gnc.inventory_edit_actor',actor.id::text,true);
  result:=private.enqueue_drive_reclass_inquiry_v7_rep_impl(p_payload);
  perform set_config('gnc.inventory_edit_actor',previous_edit_actor,true);
  perform set_config('gnc.sales_rep_operation_actor',previous_scope,true);
  return result;
exception when others then
  perform set_config('gnc.inventory_edit_actor',previous_edit_actor,true);
  perform set_config('gnc.sales_rep_operation_actor',previous_scope,true);
  raise;
end
$function$

CREATE OR REPLACE FUNCTION public.get_inventory_reclass_move_status_v1(p_actor_id uuid, p_command_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor_profile public.profiles%rowtype; batch_row private.ph_inventory_reclass_batch_receipts_v1%rowtype; actor_role text; permission_scope text; status_value text;
begin
  if coalesce(auth.role(),'') <> 'service_role' then raise exception using errcode='42501',message='INVENTORY_RECLASS_FORBIDDEN'; end if;
  select * into actor_profile from public.profiles p where p.id=p_actor_id and p.disabled_at is null
    and (p.locked_until is null or p.locked_until<=now()) and not p.must_change_password;
  if actor_profile.id is null then raise exception using errcode='42501',message='INVENTORY_RECLASS_PROFILE_INACTIVE'; end if;
  actor_role:=private.normalized_profile_role(actor_profile.role);
  if actor_role not in ('ADMIN','ADMINISTRATOR','MANAGER','EVAL','EVALUATOR') and actor_role not like '%EVAL%' then raise exception using errcode='42501',message='INVENTORY_RECLASS_FORBIDDEN'; end if;
  select e.access_scope into permission_scope from private.get_effective_app_permissions_v1(actor_profile.id,private.resolve_app_access_policy_id_v1(false)) e
    where e.permission_key='drive.reclass.submit' and e.allowed limit 1;
  if permission_scope is null then raise exception using errcode='42501',message='INVENTORY_RECLASS_PERMISSION_REQUIRED'; end if;
  select * into batch_row from private.ph_inventory_reclass_batch_receipts_v1 b where b.actor_id=p_actor_id and b.command_id=p_command_id;
  if batch_row.request_id is null then return jsonb_build_object('ok',true,'status','missing','requestId',null,'movements','[]'::jsonb); end if;
  select case when bool_or(m.status='conflict') then 'conflict' when bool_or(m.status='pending') then 'pending' else 'acknowledged' end
    into status_value from private.ph_inventory_reclass_movements_v1 m where m.request_id=any(batch_row.child_request_ids);
  return batch_row.result || jsonb_build_object('status','applied','importStatus',coalesce(status_value,'acknowledged'),
    'movements',(select coalesce(jsonb_agg(jsonb_build_object('line',m.line_index,'direction',m.direction,
      'destinationSeason',m.destination_season,'quantity',m.quantity,'sourceUniqueId',m.source_unique_id,
      'destinationUniqueId',m.destination_unique_id,'status',m.status,'conflictReason',m.conflict_reason)
      order by m.request_id,m.line_index),'[]'::jsonb) from private.ph_inventory_reclass_movements_v1 m
      where m.request_id=any(batch_row.child_request_ids)));
end
$function$
